(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-d-2-moe-dual-routing-and-dynamic-sch-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-1\">一 · 现场：一台端侧盒子上的长尾请求潮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-2\">二 · 旧路由的数学：容量因子为什么必然浪费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-3\">三 · 旧调度的代价：批窗口、KV 水位与阶段竞争</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-4\">四 · 为什么非改不可：静态化的三重错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-5\">五 · 旧方案留下的接口缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-6\">六 · 端侧请求形态：长尾长度与到达节律如何压出批窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-7\">七 · 负载如何塑造方案：热度表滞后与重路由幅度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-8\">八 · 批大小与容量因子的联动：从静态超参到运行时变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-9\">九 · SLO 与长尾：尾延迟作为准入与重路由的裁决量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-10\">十 · 方案反过来限制负载：准入、抖动与可迁移性边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-11\">十一 · 执行层的数据通路：从 top-k 路由到分组 GEMM 的精度落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-12\">十二 · 累加精度与误差传播：为什么分组 GEMM 的 K 维累加不能省</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-13\">十三 · Blackwell 特性如何改变精度与吞吐的取舍：tcgen05、TMEM、2-SM MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-14\">十四 · 预填与解码共享权重下的精度一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-15\">十五 · 精度选择反馈到调度闭环：一个可执行的判断链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-16\">十六 · 显存账本的四个账户与端侧约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-17\">十七 · 分页与块压缩：KV的粒度决定调度自由度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-18\">十八 · 复用与卸载：权重常驻集是调度变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-19\">十九 · 带宽瓶颈的位置：权重读取、KV读取与搬运三者之争</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-20\">二十 · 一个可复算的显存预算实例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-21\">二十一 · 账本滞后与抖动：水位估计的工程边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-22\">二十二 · 批窗口与容量因子：把静态超参变成运行时决策变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-23\">二十三 · 连续批处理与 chunked prefill：预填窗口按 SLO 预算切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-24\">二十四 · 优先级与抢占：热点专家队列作为准入信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-25\">二十五 · 分离式预填/解码在单设备上的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-26\">二十六 · 尾延迟怎么压：三个闭环与一个抖动约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-27\">二十七 · 切分维度：为什么端侧单设备也要谈 TP/EP/PP/DP</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-28\">二十八 · All-to-All 与 All-Reduce 的代价公式：通信何时压过计算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-29\">二十九 · NVLink 5、NVSwitch 与 NIXL：跨设备时的通信骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-30\">三十 · 通信与调度的耦合：重路由幅度就是通信预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-31\">三十一 · 失败模式与工程判据：什么时候不该并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-32\">三十二 · 并行拓扑的边界：单设备分组执行与跨设备扩展的代价断层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-33\">三十三 · 精度塌陷：从“数值可疑”到“语义崩坏”的分级诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-34\">三十四 · OOM与显存碎片：水位监控与换出策略的失效点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-35\">三十五 · 批抖动：容量因子动态调整的振荡与收敛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-36\">三十六 · 尾延迟：SLO预算被谁吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-37\">三十七 · 静默降级：没有报错的质量流失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-38\">三十八 · 监控闭环与回滚的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-39\">三十九 · 基准口径的三层结构：模型档、设备档、负载档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-40\">四十 · batch 与并发不是两个独立旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-41\">四十一 · 指标怎么读：TTFT、TPOT、吞吐、显存、功耗各自的口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-42\">四十二 · 哪些提升不可比：四类典型错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-43\">四十三 · 消融该怎么读：三个可核验维度与它们的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-44\">四十四 · 把基准读成容量规划的输入边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-45\">四十五 · 迁移到非 MoE 稠密模型：双路由失去作用点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-46\">四十六 · 迁移到不同专家粒度与共享专家结构：重路由的自由度被压缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-47\">四十七 · 迁移到多设备与分离式预填/解码：单设备假设失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-48\">四十八 · 迁移到不同领域负载：长尾形态决定调度层参数是否成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-49\">四十九 · 数值精度与底层实现的迁移空白</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-50\">五十 · 规模上限与适用边界的工程判断</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:572px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 572.4 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求到达后按长度与SLO预算入队，调度层读取专家热度表与KV水位决定批…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填阶段token级门控产生top-k专家候选，负载感知二次路由将热点…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按专家分组聚合token，执行分组GEMM并写回中间激活，同时更新专家…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码阶段逐token路由，调度层按当前KV占用动态调整并发批与容量因子…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">KV块按水位压缩或换出，热点专家权重常驻，冷门专家按需换入，完成响应并…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-1\">一 · 现场：一台端侧盒子上的长尾请求潮</h3>\n<p>设想一台单卡端侧推理盒子，显存固定，带宽固定，对外承诺的是尾延迟 SLO 而不是平均吞吐。请求流不是均匀的：短问答、长预填、多轮续写混在一起到达，长度呈长尾分布。MoE 模型的门控在 token 级做 top-k 选择，每个 token 只激活少数专家，但激活的是哪几个专家完全由输入决定。于是同一批里，某些专家被大量 token 挤爆，另一些专家几乎空转。这就是端侧 MoE 推理的原始现场：稀疏性带来算力节省，却把负载倾斜、显存碎片和 SLO 抖动一并带进了单设备。</p>\n<p>旧方案在这个现场里的主流做法可以概括为三层静态化。路由层用固定的 token 级 top-k 门控，选完就走，不做任何二次分配；调度层用固定批大小加固定容量因子（capacity factor），即按“每个专家最多容纳 C_e 个 token”预留缓冲；执行层按专家聚合做 GEMM，预填与解码各自占用资源，KV cache 按最大可能长度预留。三层都把“专家会被激活多少”当成先验常量，而现场恰恰是变量。</p>\n<p>代价首先落在尾延迟上。热点专家的队列长度超过容量因子后，溢出 token 要么被丢弃（drop），要么被排队等待，前者伤精度，后者伤 SLO。固定容量因子为了不丢 token 只能往大里设，于是每个专家都按最坏情况预留显存，冷门专家的预留空间全程空转。端侧显存本就紧张，这种“按峰值预留、按均值使用”的分配直接制造碎片：预留块被占住却不能复用，KV cache 想扩张时找不到连续空间。</p>\n<p>第二个代价是预填与解码的资源竞争。预填阶段一次处理大量 token，门控输出的专家分布瞬时极宽，几乎打满所有专家；解码阶段逐 token 路由，批内专家分布快速漂移。旧方案让两个阶段各自持有专家权重副本或各自排队，权重重复驻留抬高显存占用，两个阶段的执行窗口互相挤压，SLO 预算在阶段切换处最容易失守。端侧单设备的带宽有限，权重换入换出的开销直接体现为解码 token 间隔的尖峰。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-2\">二 · 旧路由的数学：容量因子为什么必然浪费</h3>\n<p>把旧方案的代价写成式子最清楚。设批 b 内专家 e 收到 n_e(b) 个 token，容量为 C_e，单 token 在专家 e 上的执行代价为 L_e，KV 占用为 KV(b)，权重惩罚系数为 λ。旧方案固定 C_e，其代价为：</p>\n<div class=\"formula\">$$\\text{cost}(b)=\\sum_{e}\\max\\left(0,\\frac{n_e(b)}{C_e}-1\\right)\\cdot L_e+\\lambda\\cdot\\text{KV}(b)$$</div>\n<p>第一项是溢出惩罚：n_e 超过 C_e 的部分按比例乘上执行代价，代表排队或丢弃的损失；第二项是显存代价。旧方案的问题在于 C_e 是离线定的常量，而 n_e(b) 是随输入剧烈波动的随机量。为了让第一项在长尾请求下不爆炸，C_e 必须按 n_e 的高分位设定，于是绝大多数批里 n_e 远小于 C_e，预留的显存全程闲置，第二项的 λ·KV(b) 被静态抬高。反过来，若 C_e 按均值设定，长尾批一到，第一项立刻飙升，尾延迟失守。这就是静态容量因子的两难：它把一个运行时决策变量错当成了部署期超参。</p>\n<p>更细的代价在分组 GEMM 的粒度上。执行层按专家分组聚合 token，若某专家只收到极少数 token，它仍要占一次分组 GEMM 的启动开销与权重读取带宽；若某专家收到远超 C_e 的 token，分组 GEMM 要么分多次启动，要么在容量边界截断。端侧带宽是稀缺资源，冷门专家的“空转启动”和热点专家的“截断重排”都在浪费带宽。旧方案没有机制把这两类浪费区分开，只能整体调大 C_e 来买平安。</p>\n<p>一个具体例子：一个长尾混合批到达，短请求与长预填混排。token 级门控给出 top-k 后，热度表显示专家 e* 的队列长度已超容量因子，而相邻的专家 e′ 副本几乎空闲。旧方案在此处没有二次路由，溢出 token 只能排队等 e*，或者被丢弃后由残差路径兜底。排队使该批的尾延迟被单个专家钉住，丢弃则让输出分布偏移。无论哪种，SLO 预算都在这个批上被消耗殆尽，后续批被迫缩小窗口，吞吐跟着下滑。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-3\">三 · 旧调度的代价：批窗口、KV 水位与阶段竞争</h3>\n<p>调度层的旧做法是固定批窗口加固定并发度。批窗口按离线压测的吞吐最优点设定，并发度按最大 KV 预留量反推。问题在于端侧请求的长尾性使“最优点”随负载漂移：短请求批里 KV 水位低，固定窗口偏保守，算力闲置；长预填批里 KV 水位骤升，固定窗口偏激进，显存溢出风险上升。旧方案没有把 KV 水位纳入批决策，批大小与显存占用是两条互不相看的控制回路。</p>\n<p>KV 的代价可以按块来估。设块大小为 B_kv，水位为 W，压缩比例为 r(W)，换出阈值为 W_out。旧方案按最大序列长度预留 KV，实际占用远低于预留，碎片来自“预留了但不能给别的请求用”。端侧显存里，专家权重常驻部分与 KV 块竞争同一片空间，权重换入换出与 KV 压缩换出互相踩踏，带宽在两者之间来回撕扯。解码阶段每生成一个 token 都要读一次 KV，水位高时读带宽被 KV 占满，专家权重的读取被挤到后面，token 间隔出现尖峰。</p>\n<p>预填与解码的阶段竞争在旧方案里是硬分割：预填窗口与解码窗口按时间片轮转，权重在切换处重新驻留。端侧带宽下，一次权重重新驻留的代价足以吃掉若干个解码步的预算。旧方案用“共享权重但各自排队”缓解，却没有分时复用的显式预算分配，结果是预填批一长，解码的尾延迟就被拖长；解码并发一高，预填的排队又反过来推高首 token 延迟。SLO 是尾延迟约束，两个阶段的最坏情况叠加，旧方案的固定窗口无法同时守住两端。</p>\n<p>举例：一个多轮续写请求与一个长预填请求同时到达。旧方案把两者放进同一固定窗口，长预填占满专家权重读取带宽，多轮续写的解码步被推迟，其尾延迟超出预算；调度器为了守住 SLO 缩小窗口，长预填被切成更多小批，首 token 延迟上升，整体吞吐下降。这个循环在端侧单设备上反复出现，正是论文要打破的现场。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-4\">四 · 为什么非改不可：静态化的三重错配</h3>\n<p>把旧方案的痛点归拢，是三重错配。第一重是路由与负载的错配：token 级 top-k 只看 token 与专家的亲和度，不看设备级队列长度，热点专家溢出时没有二次分配通道。第二重是容量与波动的错配：容量因子是离线常量，n_e(b) 是运行时随机量，两者之间的缺口只能用显存预留或 token 丢弃来填。第三重是阶段与预算的错配：预填与解码共享权重却各自排队，SLO 预算没有在阶段间显式分配，最坏情况叠加。</p>\n<p>这三重错配在端侧被放大。云端可以用专家并行把热点专家摊到多卡，用 All-to-All 把溢出 token 送到远端副本；端侧只有单设备，没有跨设备通道，溢出只能在本地的低负载副本间重分配。云端可以用大显存池吸收容量因子的浪费，端侧显存固定，碎片直接转化为换出与压缩的带宽开销。云端 SLO 常用平均吞吐加宽松尾约束，端侧 SLO 以尾延迟为主约束，热点专家排队长度就是准入与重路由的触发信号。旧方案在云端尚可，搬到端侧就变成必须改的对象。</p>\n<p>代价的量化方向是清楚的：热点专家排队长度直接决定尾延迟的分位点，容量因子与 n_e 的缺口直接决定预留显存的空转比例，KV 水位与批窗口的脱钩直接决定显存溢出与换出频率。论文没有给出具体数字，但机制上的因果链是完整的——只要容量因子仍是常量，缺口就必然存在；只要路由没有二次分配，热点排队就必然钉住尾延迟；只要阶段预算不显式分配，SLO 的最坏情况就必然叠加。这三条不是调参能绕过的，必须把容量因子从静态超参变成运行时决策变量，把专家热度与 KV 水位纳入批调度闭环。</p>\n<p>一个反例说明旧方案的天花板：即使把容量因子调到离线最优，长尾突变一到，n_e 的分布整体右移，最优常量立刻失效；调度器只能靠缩小批窗口来降风险，吞吐随之下滑，而尾延迟并未真正被削平，只是被摊到了更多小批上。端侧带宽下，小批意味着更多的权重读取启动开销，单位 token 的带宽成本上升，形成“越保守越慢”的负循环。这正是论文主张双路由与动态调度协同的工程动机。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-5\">五 · 旧方案留下的接口缺口</h3>\n<p>从工程接口看，旧方案缺三个可写入口。路由层缺一个“溢出通道”：token 级门控输出 top-k 与置信度后，没有地方接收“该专家队列已超容量因子”的信号并做重分配。调度层缺一个“热度与水位联合视图”：批窗口决策只看队列长度或只看显存，缺一张同时含专家热度表与 KV 块水位的表。执行层缺一个“分时复用预算”：预填与解码共享权重，但没有显式的执行窗口分配，权重驻留与换出的时机由各自排队决定而非由 SLO 预算决定。</p>\n<p>这三个缺口对应三类系统代价。溢出通道缺失，代价是热点专家排队长度无界，尾延迟被单点钉住；联合视图缺失，代价是容量因子与批大小各自为政，显存碎片与 KV 换出频率双高；分时预算缺失，代价是阶段切换处的权重重新驻留吃掉解码步预算，首 token 延迟与 token 间隔同时恶化。端侧单设备的带宽把这些代价直接放大为可观测的尖峰，而不是云端可以被池化吸收的噪声。</p>\n<p>论文的切入正是把这三个入口补上：路由侧在 token 级门控之外加设备级负载感知二次路由，把热点专家溢出 token 重分配到低负载副本；调度侧维护专家热度表与 KV 块水位，按二者动态决定批窗口与容量因子；执行侧按专家分组做分组 GEMM，预填与解码共享专家权重但分时复用，KV 按水位分档压缩与换出。这些机制在后续部分展开，此处只需确认旧方案的接口缺口是真实存在的、且不是靠调常量能补上的。</p>\n<p>最后落在一个工程判断上：端侧 MoE 推理的瓶颈不是单个算子的效率，而是路由决策、容量决策与阶段预算三者之间的耦合。旧方案把三者拆成三条静态回路，耦合点全部落在最坏情况上，尾延迟因此不可控。把容量因子变成运行时决策变量、把专家热度与 KV 水位纳入批调度闭环，是打破这个耦合的最小改动面；而二次路由的重分配幅度必须受限，否则热度表的滞后估计会在长尾突变下引发批内路由抖动，这一点在旧方案的静态回路里根本不存在，也就成了新机制必须自己承担的代价。</p>\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-6\">六 · 端侧请求形态：长尾长度与到达节律如何压出批窗口</h3>\n<p>D²MoE 的调度层不是先定批大小再去凑请求，而是反过来：先读 SLO 预算，再切预填窗口。端侧请求的长度分布是长尾的，短请求（几十 token 的问答、指令）与长预填（数千 token 的文档摘要、检索增强上下文）混在同一到达流里。这个混合形态直接决定了批窗口不能是一个固定值——固定批大小在短请求密集时会浪费显存，在长预填密集时会撑爆 KV 水位。可核查的测量口径是：按请求输入长度分桶（例如 <256、256–1024、1024–4096、>4096 token 四档），统计每桶的到达率与桶内长度方差，再乘以桶的平均预填 token 数得到每桶的预填工作量。批窗口的切分依据是 SLO 预算里预填阶段可用的时间片，而不是请求个数。</p>\n<p>这里有一个容易被忽略的耦合：长尾不是长度分布的长尾，而是“长度×专家分布”的联合长尾。一个短请求如果路由到热点专家，它的排队代价可能超过一个长请求路由到冷门专家。所以调度层维护的专家热度表必须与长度分桶交叉统计，否则批窗口会把短请求和长请求混在一起，热点专家队列被短请求的低计算量掩盖，尾延迟在解码阶段才暴露。测量口径上，应记录每个批窗口内“热点专家 token 数 / 该专家容量因子”的比值分布，而不是只看平均利用率。</p>\n<p>并发度在端侧不是外部给定的常数，而是 KV 水位的函数。解码阶段逐 token 路由使批内专家分布快速漂移，同一批内不同请求的 KV 增长速率不同，长请求的 KV 块膨胀快，短请求完成后释放块。调度层按当前 KV 占用动态调整并发批，本质是把并发度变成显存水位的反馈控制量。代价是：并发下调会降低解码吞吐，但守住尾延迟；并发上调会提高吞吐，但 KV 水位逼近上限时压缩与换出触发，带宽开销上升。这个折中在单设备上无法用增加副本化解，只能靠批窗口的时间片分配。</p>\n<div class=\"formula\">$$\\text{cost}(b)=\\sum_{e}\\max\\left(0,\\frac{n_e(b)}{C_e}-1\\right)\\cdot L_e+\\lambda\\cdot\\text{KV}(b)$$</div>\n<p>公式里第一项是热点专家溢出队列的排队代价，$n_e(b)$ 是批 $b$ 内路由到专家 $e$ 的 token 数，$C_e$ 是该专家的容量因子，$L_e$ 是单 token 在该专家上的执行延迟；第二项是 KV 占用代价，$\\lambda$ 是显存水位到延迟的折算系数。这个 cost 不是离线算一次，而是调度层在每个批窗口切分时对候选批做在线评估：把长预填请求放进批窗口会抬高 $n_e(b)$ 在热点专家上的集中度，把短请求放进批窗口会抬高 KV 周转率。批窗口的选择就是在这个 cost 上做贪心切分，SLO 预算作为硬约束截断。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-7\">七 · 负载如何塑造方案：热度表滞后与重路由幅度</h3>\n<p>负载形态对方案的第一个塑造是热度表的更新频率。端侧到达流是突发的，一个热点专家可能在几十个请求内从冷变热，滑动窗口统计如果窗口太长，热度表滞后，容量因子跟不上，热点队列溢出；窗口太短，统计噪声大，容量因子抖动，重路由频繁触发。论文的处理是把离线校准得到的专家热度先验作为初值，运行时用滑动窗口在线更新，门控与重路由阈值由校准集上的尾延迟约束确定。这意味着阈值不是拍脑袋定的，而是在校准集上扫描“重路由触发时的尾延迟”得到的部署期参数。</p>\n<p>第二个塑造是重路由幅度的限制。负载感知二次路由把热点专家溢出 token 重分配到低负载副本，但长尾突变下如果重路由幅度不受限，批内路由抖动会让分组 GEMM 的聚合模式反复变化，执行层的分组边界不稳定，反而增加调度开销。论文明确要求限制重路由幅度以避免批内路由抖动。可核查的口径是：统计每个批窗口内被二次路由的 token 占比，以及这些 token 在原专家与新专家之间的切换次数；占比过高说明容量因子估计偏保守，切换次数过高说明热度表噪声大。</p>\n<p>第三个塑造是预填与解码的资源竞争。预填阶段 token 级门控产生 top-k 专家候选，计算密集但 KV 增长一次性完成；解码阶段逐 token 路由，计算量小但 KV 持续增长。两者共享专家权重但分时复用，按 SLO 预算分配执行窗口。负载形态决定了这个时间片比例：长预填密集时预填窗口要拉长，否则预填排队把尾延迟推高；解码密集时预填窗口要压缩，否则 KV 水位在预填阶段就被抬高，解码阶段没有余量做块压缩。这个比例是运行时决策，不是静态配置。</p>\n<p>反过来，方案也限制负载。容量因子动态调整意味着系统能接纳的并发不是无限的：当 KV 水位逼近上限，调度层下调批大小，新到达请求在准入队列里等待，等效于把负载削峰。热点专家队列长度作为准入与重路由触发信号，队列超容量因子时新请求被延迟准入，这是方案对负载的反向限制。代价是准入延迟计入尾延迟，所以队列阈值必须与 SLO 预算对齐，不能设得过紧。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-8\">八 · 批大小与容量因子的联动：从静态超参到运行时变量</h3>\n<p>固定容量因子的问题在长尾请求下最明显：容量因子按平均专家负载设定，长尾请求路由到热点专家时队列溢出，冷门专家容量闲置，显存被预留但不用，碎片化。D²MoE 把容量因子变成运行时决策变量，调度层按专家热度表与 KV 水位动态决定。具体机制是：每个专家维护一个容量因子，初值来自离线校准，运行时按滑动窗口的热度统计上调或下调；上调意味着为该专家预留更多分组 GEMM 的聚合空间，下调意味着释放预留给其他专家或 KV 块。</p>\n<p>批大小与容量因子是联动的，不是独立调节。批大小决定批内 token 总数，容量因子决定单专家能容纳的 token 数，两者相乘约束了批内专家分布的集中度。调度层的做法是先按 KV 水位定批大小上限，再按热度表定各专家容量因子，最后用 cost 公式检查候选批是否超预算；超预算时要么缩小批大小，要么触发二次路由把溢出 token 移走。这个顺序很重要：先定批大小再定容量因子，可以避免容量因子被批大小反向拉扯导致抖动。</p>\n<p>系统代价体现在三个方向。延迟上，容量因子下调会减少分组 GEMM 的并行度，单批执行时间变长；吞吐上，容量因子上调会占用更多显存做聚合缓冲，挤压 KV 块空间；显存上，容量因子的动态调整本身需要元数据，专家热度表与 KV 水位表常驻显存，端侧显存有限时这部分开销不可忽略。论文未给出具体数字，但机制上这三者的折中由 SLO 预算的尾延迟约束来裁决，而不是由平均吞吐裁决。</p>\n<p>一个具体例子：一个长尾混合请求批次到达，调度层先按 SLO 预算切出预填窗口，token 级门控给出 top-k 专家，热度表显示某专家队列超容量因子，二次路由把溢出 token 重分配到低负载副本；分组 GEMM 按专家聚合执行，解码阶段 KV 水位上升触发块压缩与冷门专家换出，批大小随水位下调以守住尾延迟。这个例子里容量因子在预填阶段被上调（因为热点专家队列超限），在解码阶段被下调（因为 KV 水位上升），同一批次内容量因子变化两次，说明它确实是运行时变量而非静态超参。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-9\">九 · SLO 与长尾：尾延迟作为准入与重路由的裁决量</h3>\n<p>端侧 SLO 以尾延迟为主约束，不是平均延迟。平均延迟在长尾请求下会被短请求拉低，掩盖热点专家排队。论文把热点专家排队长度作为准入与重路由触发信号，本质是用队列长度代理尾延迟：队列超容量因子意味着新 token 的等待时间超过预算，此时触发二次路由或延迟准入。可核查的测量口径是分位数延迟（p50、p95、p99）按请求长度分桶统计，以及每个分桶内“触发重路由的请求占比”。如果 p99 在长预填桶里显著高于短请求桶，说明预填窗口切分不足或热点专家容量因子偏保守。</p>\n<p>长尾的另一个来源是专家分布的长尾，不是请求长度的长尾。路由分布随输入变化剧烈，同一长度桶内的请求可能路由到完全不同的专家集合。所以 SLO 统计必须按“长度桶×专家热度桶”交叉分组，否则尾延迟的归因会错。论文的材料没有给出具体分位数数字，但机制上尾延迟约束是校准集上确定门控与重路由阈值的依据，这意味着阈值是尾延迟的函数，不是利用率的函数。</p>\n<p>预填与解码的 SLO 预算是分开的。预填阶段的尾延迟由批窗口切分和热点专家队列决定，解码阶段的尾延迟由 KV 水位和逐 token 路由的专家漂移决定。调度层按 SLO 预算分配执行窗口，预填窗口拉长会压缩解码窗口，解码窗口压缩会抬高解码尾延迟。这个时间片分配是零和的，端侧单设备没有额外算力可以借。代价是：SLO 预算紧时，预填与解码的窗口比例必须精确匹配负载形态，否则一侧的尾延迟会挤占另一侧的预算。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-10\">十 · 方案反过来限制负载：准入、抖动与可迁移性边界</h3>\n<p>方案对负载的反向限制有三个可核查的机制。第一是准入延迟：热点专家队列超容量因子时新请求延迟准入，等效于把突发负载削峰，代价是准入延迟计入尾延迟。第二是重路由幅度限制：长尾突变下限制二次路由的 token 占比，避免批内路由抖动，代价是部分溢出 token 仍在热点专家排队，尾延迟削平不彻底。第三是 KV 压缩档位：按显存水位分档压缩与换出，水位高时压缩比例上调，代价是压缩与换出的带宽开销挤占解码带宽。</p>\n<p>这三个限制共同定义了方案的负载包络：超过包络的负载形态（例如极长预填密集且专家分布高度集中）会让尾延迟超出 SLO，此时方案的选择是延迟准入而非硬扛。这个包络是端侧单设备的固有限制，论文的局限里明确说单设备场景结论不能直接外推到多设备专家并行与分离式预填/解码的容量规划。可迁移的部分是容量因子的动态化思路和热度表与 KV 水位的闭环，不可迁移的是单设备的时间片零和约束。</p>\n<p>热度表与 KV 水位估计存在滞后，长尾突变下重路由可能抖动，这是方案对负载形态的敏感点。测量口径上应记录热度表更新周期与请求到达间隔的比值，比值过大说明滞后明显，抖动风险高；同时记录重路由触发后一个窗口内的反向重路由次数，反向次数高说明阈值设置过敏感。这些口径不依赖具体数字，只依赖机制，可以在部署时用来判断参数是否越界。</p>\n<p>最后落在工程判断上：端侧 MoE 推理的负载形态不是外部输入，而是与调度方案共同演化的。批窗口切分改变请求的排队顺序，容量因子改变专家队列长度，准入延迟改变到达流的有效并发，三者构成一个反馈环。D²MoE 的双路由与动态调度把这个反馈环显式化，用 cost 公式做在线裁决，用 SLO 尾延迟约束做硬截断。工程上要守住的是反馈环的稳定性：热度表窗口、重路由幅度、容量因子调整步长这三个参数必须一起校准，单独调一个会把抖动转移到另一个环节。</p>\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-11\">十一 · 执行层的数据通路：从 top-k 路由到分组 GEMM 的精度落点</h3>\n<p>D²MoE 的执行层并不存在一个“通用 GEMM”内核，它的基本形态是<strong>按专家分组的分组 GEMM</strong>：调度层把批窗口内所有 token 的专家分配结果交给执行层，执行层按专家 ID 把 token 聚成若干不规则的 M×K 子矩阵，每个子矩阵乘上对应专家的权重块。这个数据通路的数值精度问题集中在三个位置：门控打分（决定 top-k 与二次路由）、专家权重与激活的乘法、以及跨专家聚合写回中间激活时的累加。论文材料没有给出量化方案，因此本部分只能从机制层面说明这三个位置在 Blackwell 上分别由哪类指令承担、精度如何选、误差如何传播，以及每一步的系统代价落在延迟、带宽还是显存上。</p>\n<p>门控打分通常是 token 隐状态与门控矩阵的小 GEMM，输出维度等于专家数。它的数值要求与专家 GEMM 不同：top-k 选择对排序敏感，对绝对数值不敏感，因此门控可以用较低精度（FP16 甚至 BF16）计算，但 softmax 与 top-k 的比较必须在较高精度下完成，否则两个接近的专家分数在低精度下翻转会直接改变路由结果，进而改变整批的专家分组形态。二次路由的触发条件是“热点专家队列超容量因子”，这是一个整数比较，不涉及浮点误差，但它依赖门控输出的置信度，置信度若因低精度门控而抖动，重路由的幅度限制机制就会被频繁触发。</p>\n<p>专家 GEMM 是精度与吞吐的主战场。端侧单设备的算力有限，专家权重常驻显存、冷门专家按需换入，权重块的精度直接决定换入带宽需求。以 FP16 权重为例，一个专家若为 d_model×d_ff 的两个矩阵，换入一次的数据量是 2×d_model×d_ff×2 字节；若改为 FP8，同样结构的换入量减半，冷门专家换入的延迟随之下降。但 FP8 的尾数位宽窄，专家输出的动态范围压缩后，跨专家聚合时的累加误差会被放大。这就是为什么累加精度必须与权重精度分开讨论：权重可以是 FP8，累加器应保持 FP32 或至少 BF16 的宽累加，否则热点专家与冷门专家输出相加时，小量级专家的贡献会被大量级专家的舍入误差吞掉。</p>\n<div class=\"formula\">$$\\text{err}_{\\text{agg}}=\\sum_{e\\in S}\\left|\\,\\hat{y}_e-y_e\\,\\right|+\\left|\\,\\text{fl}\\Big(\\sum_{e\\in S}\\hat{y}_e\\Big)-\\sum_{e\\in S}\\hat{y}_e\\,\\right|$$</div>\n<p>上式逐项解释：第一项是各专家自身 GEMM 在低精度权重与低精度乘加下的输出偏差之和，$S$ 是当前 token 命中的专家集合（top-k 加上二次路由重分配后的实际集合）；第二项是聚合写回时的舍入偏差，$\\text{fl}(\\cdot)$ 表示按累加器精度做浮点舍入。两项的量级关系决定了精度方案：若第一项远大于第二项，提升累加精度收益有限，应优先提升权重精度或对热点专家做更高精度的副本；若第二项与第一项可比，说明累加器位宽不足，跨专家求和本身在丢信息。D²MoE 的二次路由会把溢出 token 从热点专家搬到低负载副本，这改变了 $S$ 的构成，也就改变了误差结构——重分配后的 token 可能落到一个精度档位不同、或权重刚被换入的专家上，误差不再由原热点专家主导。</p>\n<p>具体例子：一个长尾批次中某热点专家队列长度超过容量因子，二次路由把溢出 token 重分配到低负载副本。若副本专家权重刚从换出状态换入、且以 FP8 存储，这批 token 的输出误差由副本的量化误差主导，而非原热点专家；聚合时若累加器为 FP16，热点专家与副本专家输出量级差异大，求和结果的低位被截断。工程判断是：重路由目标专家的精度档位应与源专家一致，否则二次路由在削平排队的同时引入了不可控的数值偏差。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-12\">十二 · 累加精度与误差传播：为什么分组 GEMM 的 K 维累加不能省</h3>\n<p>分组 GEMM 的 K 维是隐层维度，累加长度长，是误差积累的主要来源。Blackwell 的第五代 Tensor Core 在 MMA 指令内部提供宽累加通路，但累加器的实际位宽取决于指令形态与寄存器/TMEM 的分配。对端侧推理而言，K 维累加的误差有两个可观测后果：一是专家输出本身的数值漂移，二是当同一 token 被二次路由拆分到多个专家时，部分和相加的顺序与精度决定了最终激活。后者是 D²MoE 特有的：token 级 top-k 本来就把一个 token 的贡献分散到 k 个专家，二次路由又可能把其中一部分搬到副本，聚合的项数增加，累加误差的方差随之增加。</p>\n<div class=\"formula\">$$\\sigma^2_{\\text{sum}}\\approx\\sum_{e\\in S}\\sigma^2_{e}+2\\sum_{e&lt;e'}\\text{Cov}(\\hat{y}_e,\\hat{y}_{e'})$$</div>\n<p>逐项解释：$\\sigma^2_e$ 是单个专家输出的误差方差，由该专家的权重精度、激活精度与 K 维累加位宽共同决定；协方差项来自专家之间的相关性——同一 token 的不同专家输入是同一隐状态，若激活量化是确定性的，误差在专家间可能正相关，聚合后方差被放大而非平均掉。这解释了为什么“多专家平均能降噪”的直觉在 MoE 推理中不成立：top-k 的专家输出不是独立同分布的估计，它们是同一输入的不同线性变换，量化误差同源。工程上，若把激活量化到 FP8，应保证同一 token 在所有命中专家上使用同一量化尺度，避免各专家独立量化引入额外的不相关误差项，反而让协方差项失去可预测性。</p>\n<p>系统代价方面，累加精度直接换取寄存器与 TMEM 占用。FP32 累加器在 tcgen05 的 TMEM 中占用的列数与 FP16 不同，TMEM 容量固定，累加器位宽越高，能同时驻留的 MMA 累加块越少，分组 GEMM 的并行度下降。端侧单设备的算力波动本就剧烈，TMEM 占用上升会把原本可以并行的多个专家分组串行化，热点专家的排队时间被拉长——这与调度层削平排队的目的直接冲突。因此累加精度的选择不是纯数值问题，它通过 TMEM 占用反馈到调度层的批窗口决策：批窗口越大，同时活跃的专家分组越多，TMEM 压力越大，累加精度若不能降档，批窗口就只能收窄。</p>\n<p>具体例子：解码阶段逐 token 路由，批内专家分布快速漂移，同一时刻活跃专家数可能远小于批大小但分组数多。若每个分组都申请 FP32 累加的 TMEM 块，TMEM 成为瓶颈，分组 GEMM 被迫按专家串行执行，单 token 的解码延迟随批内专家数上升。反之若对冷门专家分组用 BF16 累加、热点专家保留 FP32，TMEM 占用按热度分层，调度层可以用专家热度表直接决定每个分组的累加档位——这把数值精度选择变成了运行时决策，与容量因子的动态化是同一套闭环。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-13\">十三 · Blackwell 特性如何改变精度与吞吐的取舍：tcgen05、TMEM、2-SM MMA</h3>\n<p>tcgen05 是 Blackwell 上承担矩阵乘加的新一代指令族，它的关键变化是累加器落在 TMEM 而非寄存器堆，MMA 的发起与累加分离，异步性强。对 D²MoE 的分组 GEMM 而言，这意味着一个专家分组的 MMA 可以在数据搬运（权重换入、激活聚合）进行时保持累加器驻留，减少流水线气泡。代价是 TMEM 成为稀缺资源：TMEM 按列分配，每个累加块占用的列数与 M、N、累加位宽相关，分组 GEMM 的不规则 M 维（每个专家的 token 数不同）导致 TMEM 分配碎片化，热点专家分组 M 大、占用列多，冷门专家分组 M 小、占用列少但仍有固定开销。</p>\n<p>2-SM MMA 让两个 SM 协作完成一次 MMA，把单个 MMA 的 N 维或 M 维扩大，适合大专家分组。它的收益在热点专家上最明显：热点专家队列长、聚合后的 M 大，2-SM MMA 减少跨 SM 的数据重复读取，权重块只搬一次。但 2-SM MMA 要求两个 SM 的 TMEM 协同分配，冷门专家分组若强行使用 2-SM 形态，固定开销摊薄不了，反而浪费一个 SM 的算力。这与二次路由的目标一致：把热点专家的溢出 token 搬到低负载副本，副本分组 M 小，应使用单 SM MMA 与较低累加档位，形成“热点大分组高精度、冷门小分组低开销”的分层执行形态。</p>\n<table class=\"mini\"><thead><tr><th>执行形态</th><th>适用分组</th><th>TMEM 占用</th><th>精度取舍</th><th>系统代价</th></tr></thead><tbody><tr><td>单 SM MMA</td><td>冷门/副本专家，M 小</td><td>低，列数少</td><td>BF16 累加可接受</td><td>算力利用率低但换入带宽省</td></tr><tr><td>2-SM MMA</td><td>热点专家，M 大</td><td>高，双 SM 协同</td><td>FP32 累加保聚合精度</td><td>权重搬运减半，TMEM 压力上升</td></tr><tr><td>tcgen05 异步累加</td><td>预填阶段大分组</td><td>中高，累加驻留</td><td>权重 FP8 + FP32 累加</td><td>流水线气泡减少，显存带宽成瓶颈</td></tr></tbody></table>\n<p>第五代 Tensor Core 的吞吐提升不改变带宽约束。端侧单设备的显存带宽有限，专家权重常驻与按需换入的结合意味着权重搬运是主要开销之一。精度降档（FP16→FP8→NVFP4）降低的是权重搬运字节数，但 NVFP4 的块缩放（block scaling）引入额外的缩放因子读取与反量化步骤，这些步骤在 Tensor Core 之外执行，占用 CUDA Core 与寄存器，可能抵消吞吐收益。对 D²MoE 这种分组不规则、M 维小的形态，NVFP4 的反量化开销摊薄困难，热点专家大分组尚可，冷门专家小分组不划算。论文材料未给出量化方案，因此这里只能给出判断准则：分组 M 超过某个阈值时 NVFP4 的带宽收益才能覆盖反量化开销，阈值由权重块大小与反量化指令吞吐共同决定，需在部署期用校准集实测，而非按理论峰值推算。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-14\">十四 · 预填与解码共享权重下的精度一致性</h3>\n<p>D²MoE 让预填与解码共享专家权重但分时复用。共享权重意味着两个阶段必须使用同一套精度档位，否则同一专家在预填与解码中输出不一致，KV 中已写入的激活与解码时重新计算的激活会产生偏差。预填阶段 M 大、分组规整，适合 FP8 权重加 FP32 累加；解码阶段 M 小、分组碎片化，若沿用 FP8 权重，反量化开销占比上升，但若为解码单独准备一份 FP16 权重副本，显存占用翻倍，与端侧有限显存直接冲突。</p>\n<div class=\"formula\">$$B_{\\text{resident}}=W_{\\text{hot}}\\cdot b_w+W_{\\text{cold}}\\cdot b_w\\cdot\\rho_{\\text{in}}+\\text{KV}_{\\text{active}}$$</div>\n<p>逐项解释：$W_{\\text{hot}}$ 是热点专家权重总量，$b_w$ 是每参数字节数（FP16 为 2、FP8 为 1、NVFP4 为 0.5 加缩放开销），$W_{\\text{cold}}$ 是冷门专家权重总量，$\\rho_{\\text{in}}$ 是冷门专家按需换入的比例，$\\text{KV}_{\\text{active}}$ 是当前活跃 KV 块占用。这个式子说明精度降档的收益集中在 $W_{\\text{hot}}\\cdot b_w$ 项：热点专家常驻，降档直接减少常驻显存，为 KV 留出空间；冷门专家按需换入，降档减少的是换入带宽而非常驻显存。预填与解码共享权重时，若热点专家用 FP8 常驻，解码阶段的小分组也要承担反量化开销；若热点专家保留 FP16，常驻显存上升，KV 水位更快触顶，触发更早的块压缩与换出。</p>\n<p>具体例子：解码阶段 KV 水位上升触发块压缩，调度层下调批大小。此时若专家权重为 FP8，反量化在每次分组 GEMM 前执行，小分组的反量化开销占比高，单 token 解码延迟上升；若权重为 FP16，无此开销但常驻显存高，KV 可用空间小，块压缩更频繁，压缩本身占用带宽。两条路径的尾延迟由不同环节主导，部署期需按 SLO 预算在两者间选点，而不是统一取一个精度档位。论文材料未给出量化精度方案，这一取舍属于部署期参数，与容量因子、KV 压缩档位同属一个校准闭环。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-15\">十五 · 精度选择反馈到调度闭环：一个可执行的判断链</h3>\n<p>把上述机制串成一条工程判断链：调度层读专家热度表与 KV 水位，决定批窗口与容量因子；执行层按分组 M 与专家热度选 MMA 形态（单 SM 或 2-SM）与累加档位；权重精度档位由常驻显存预算与换入带宽预算共同约束；二次路由的目标专家精度档位必须与源专家一致，否则聚合误差不可控。这条链的每一环都有可观测信号：专家热度表给出分组 M 的期望，KV 水位给出显存余量，尾延迟统计给出精度档位是否值得降。校准集上的尾延迟约束确定门控与重路由阈值，同一校准过程也应确定精度档位的切换点。</p>\n<p>失败模式在精度维度上的表现是：热度表滞后导致分组 M 估计偏大，执行层按大分组选了 2-SM MMA 与 FP32 累加，实际分组小，TMEM 与算力浪费，批窗口被挤窄，尾延迟反而上升；或二次路由把 token 搬到精度档位不同的副本，聚合误差在长尾请求上累积，表现为输出质量下降而非延迟上升，这类失败不会被 SLO 监控捕获，只能靠离线校准集的数值比对发现。论文材料缺少量化精度与分组 GEMM 底层细节，数值精度收益无法核验，因此工程落地时应把精度档位作为独立可回滚的部署参数，与容量因子分开管理，避免一次调整同时改变排队形态与数值形态、无法归因。</p>\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-16\">十六 · 显存账本的四个账户与端侧约束</h3>\n<p>在单设备端侧跑MoE推理，显存不是一个数字，而是四个互相挤占的账户：常驻专家权重、分组GEMM的中间激活、KV块、以及路由/调度层的元数据（热度表、块表、SLO预算）。D²MoE的显存账本必须先把这四项分开记，否则“容量因子调大一点”这种动作会同时改变激活与KV两侧的水位，尾延迟就失去可解释性。端侧设备的硬约束是容量与带宽同时紧张：权重常驻部分越大，KV可分配的块就越少，解码阶段的并发批就越小；反过来，KV水位高时把冷门专家换出，权重换入又要在解码关键路径上付出带宽代价。因此账本的核心不是“总量够不够”，而是“四个账户之间的兑换率”——每换出1字节专家权重能换回多少KV块、每压缩一档KV能释放多少解码并发。</p>\n<p>把账本写成可复算的形式，先定义符号：$W_{\\text{hot}}$为热点专家常驻权重，$W_{\\text{cold}}$为按需换入的冷门专家权重，$A(b)$为批大小$b$下的激活峰值，$K(b,s)$为批大小$b$、序列长度$s$下的KV占用，$M$为元数据开销。约束是：</p>\n<div class=\"formula\">$$W_{\\text{hot}}+W_{\\text{cold}}^{\\text{resident}}+A(b)+K(b,s)+M\\le C_{\\text{HBM}}$$</div>\n<p>其中$W_{\\text{cold}}^{\\text{resident}}$是当前已换入的冷门专家子集，它是调度层的决策变量而非常量。这个不等式看起来平凡，但它把“容量因子”从超参变成了右侧的松弛量：容量因子越大，热点专家队列越短，但$A(b)$与$K(b,s)$同时上升，左侧逼近上限。D²MoE的调度层实际上是在这条约束下做在线可行性判定，而不是先定容量因子再祈祷不OOM。</p>\n<p>具体例子：假设某端侧设备HBM容量为$C_{\\text{HBM}}$，模型有$E$个专家、每个专家权重$w$字节，热点专家集合大小$h$。若$h\\cdot w$已占去容量的一半以上，则剩余空间必须同时容纳激活峰值与KV块；此时把批大小从$b_1$降到$b_2$释放的激活与KV，可能刚好够换入一个冷门专家副本以削平二次路由的目标队列。这个兑换是否划算，取决于换入权重带来的带宽开销是否小于热点排队消除带来的尾延迟收益——账本必须把这两项都记进去，否则调度会做出“省了显存、赔了延迟”的决策。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-17\">十七 · 分页与块压缩：KV的粒度决定调度自由度</h3>\n<p>KV按块管理是端侧MoE推理能做出细粒度调度的前提。若KV按请求整块分配，长尾请求里一个超长序列就会锁死一大段连续显存，批窗口无法收缩；按固定大小块分页后，KV水位变成“已分配块数/总块数”的标量，调度层可以直接读这个标量决定批窗口。D²MoE的KV块水位与专家热度表并列作为调度输入，正是因为块粒度让“水位”成为可比较、可触发的信号，而不是一个模糊的剩余量估计。</p>\n<p>块压缩按水位分档：低水位不压缩，中水位对冷块做量化压缩，高水位触发换出。压缩比例是部署期参数，按显存水位分档设定，运行时只做档位选择。代价要算清楚：压缩一档KV块，解码时每个token的注意力读取字节数下降，带宽压力缓解，但解压引入额外算力与一次额外的读写往返。设块大小为$B_k$字节、压缩比为$r$，则单块压缩后的驻留字节为$B_k/r$，而解码路径上每访问一次该块要多付出一次解压开销$c_{\\text{dec}}$。当KV带宽占总带宽的比例超过阈值时，压缩的净收益为正；反之压缩只是把带宽瓶颈从KV搬到解压算力上。</p>\n<p>可复算的KV预算：设层数$L$、KV头数$H_{kv}$、头维度$d$、每元素字节$s_b$、序列长度$S$、批大小$b$，则</p>\n<div class=\"formula\">$$K(b,S)=2\\cdot L\\cdot H_{kv}\\cdot d\\cdot S\\cdot b\\cdot s_b$$</div>\n<p>系数2来自K与V两份。举例：若$L=32$、$H_{kv}=8$、$d=128$、$s_b=1$（FP8 KV）、$S=4096$、$b=8$，则单请求KV为$2\\times32\\times8\\times128\\times4096\\times1\\approx 2.68\\times10^{8}$字节，即约256 MiB量级，八并发约2 GiB。这个量级在端侧HBM里就是“能不能开第二个批窗口”的分水岭。把$S$换成$S/2$或把$s_b$降到半字节（更激进的块压缩档），KV账户立刻让出一半空间给激活或冷门专家权重——这就是分页+压缩档位作为调度杠杆的算术基础。</p>\n<p>分页还带来碎片问题：块表本身是元数据，块越多、表越大，$M$项上升；块太小则表项膨胀、查表开销进入解码关键路径。D²MoE把KV块水位与容量因子一起调，实际上是在块大小固定的前提下用批窗口去适配水位，避免频繁重分页。工程判断是：端侧块大小应取“一次解码步的注意力读取能覆盖整块”的量级，使块内访问连续，块间换出代价可摊薄。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-18\">十八 · 复用与卸载：权重常驻集是调度变量</h3>\n<p>预填与解码共享专家权重但分时复用，是D²MoE在显存账本上最直接的一笔节省。若预填与解码各自持有一份权重副本，端侧容量根本放不下；分时复用意味着同一份$W_{\\text{hot}}$在两个阶段交替被读，代价是阶段切换时的权重驻留状态需要保持一致，且预填的长序列聚合不能把解码的权重挤出。执行层的分组GEMM按专家聚合token，预填阶段一个专家可能聚合大量token，解码阶段则每个专家只有零星token——同一份权重在两种聚合形态下被读，带宽效率差异巨大。预填是带宽友好的（大GEMM、高复用），解码是带宽不友好的（小GEMM、权重读取占比高），因此分时复用的排布应让预填窗口尽量连续，减少解码阶段被预填打断的次数。</p>\n<p>卸载策略是“热点常驻、冷门按需换入”。热点集合由热度表滑动窗口统计决定，冷门专家换入发生在二次路由把溢出token重分配到低负载副本时——注意这里的目标副本可能尚未驻留，换入本身就是二次路由的隐式代价。设换入一个专家权重的字节数为$w$、设备有效带宽为$B_{\\text{eff}}$，则换入延迟下界为$w/B_{\\text{eff}}$；若该专家在本批内只服务少量token，这笔换入在摊销后可能比让热点专家排队更贵。因此二次路由的触发条件不能只看队列长度，还要看“换入成本/预期服务token数”是否低于排队延迟的节省。论文把重路由幅度限制住以避免抖动，本质就是在控制这类换入的摊销风险。</p>\n<p>复用还有一层：KV块的换出与专家权重的换入共享同一条带宽通道。高水位时若同时触发KV压缩写回与冷门专家换入，两者会在带宽上打架，解码步的尾延迟被双向拉长。调度层需要给这两类搬运排优先级：KV换出是“保容量”，专家换入是“保队列”，在SLO预算紧张时应先保容量再谈重路由，否则会出现“换入了专家却因KV溢出被迫缩批”的自相矛盾。这是账本里最容易被忽略的耦合项。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-19\">十九 · 带宽瓶颈的位置：权重读取、KV读取与搬运三者之争</h3>\n<p>端侧MoE解码的带宽瓶颈不在算力，而在“每生成一个token要读多少字节”。解码阶段批内token到专家的分配快速漂移，分组GEMM的每个专家只聚合少量token，权重读取字节数几乎与批大小无关，于是有效带宽利用率随批大小下降而恶化。设批大小$b$、激活专家数$k$、每专家权重$w$，解码一步的权重读取量约为$k\\cdot w$（与$b$弱相关），而计算量随$b$线性增长；因此解码的算术强度近似为$b$的线性函数，$b$越小越带宽受限。这就是为什么端侧解码必须靠连续批处理把$b$撑住，而撑住$b$的前提是KV账户有余量——三个账户在此闭环。</p>\n<p>KV读取是第二条带宽流：每个解码token要读全部历史KV，读取量与$S$成正比。长尾请求的$S$大，KV读取会压过权重读取成为主瓶颈；此时块压缩档位上调的收益最明显。第三条流是搬运：专家换入与KV换出。三条流共享HBM带宽，调度层若不同时建模三者，就会出现“压缩了KV却因换入专家把带宽吃回去”的情况。可复算的判据是：设总带宽$B_{\\text{HBM}}$，权重流$B_w$、KV流$B_{kv}$、搬运流$B_m$，则解码步时间下界为</p>\n<div class=\"formula\">$$T_{\\text{step}}\\ge \\frac{k\\cdot w + K_{\\text{read}}(b,S) + B_m\\cdot t_{\\text{move}}}{B_{\\text{HBM}}}$$</div>\n<p>工程上要盯的是$B_m$的瞬时占比：搬运是突发流，短时间可占满带宽，把解码步的尾延迟拉出一个尖峰。D²MoE把预填与解码分时复用，一部分目的就是让预填的大块搬运不落在解码的带宽窗口里。端侧没有NVLink 5那样的高带宽互联可借，HBM带宽就是唯一通道，因此“搬运预算”必须显式记账，而不是当作零成本。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-20\">二十 · 一个可复算的显存预算实例</h3>\n<p>下面给一个只依赖符号、可代入实际参数复算的预算表。设设备HBM容量$C_{\\text{HBM}}$，专家数$E$、每专家权重$w$字节、热点专家数$h$、已换入冷门专家数$c$；层数$L$、KV头数$H_{kv}$、头维度$d$、KV元素字节$s_b$、序列长度$S$、批大小$b$；激活峰值按$A(b)=\\alpha\\cdot b$建模（$\\alpha$为每token激活字节的经验系数，由分组GEMM的中间张量决定）；元数据$M$按块表与热度表规模估算。</p>\n<table class=\"mini\"><thead><tr><th>账户</th><th>表达式</th><th>调度杠杆</th><th>代价方向</th></tr></thead><tbody>\n<tr><td>热点专家权重</td><td>$h\\cdot w$</td><td>热度表阈值决定$h$</td><td>$h$大则KV与激活被挤</td></tr>\n<tr><td>冷门专家驻留</td><td>$c\\cdot w$</td><td>二次路由触发换入</td><td>换入延迟摊薄风险</td></tr>\n<tr><td>激活峰值</td><td>$\\alpha\\cdot b$</td><td>批窗口</td><td>$b$大则尾延迟与显存同升</td></tr>\n<tr><td>KV</td><td>$2L H_{kv} d S b s_b/r$</td><td>压缩档位$r$、批大小$b$</td><td>解压算力与读写往返</td></tr>\n<tr><td>元数据</td><td>$M$（块表+热度表）</td><td>块大小</td><td>块小则表大、查表进关键路径</td></tr>\n</tbody></table>\n<p>复算步骤：先由$S$与$b$算出KV账户，扣除后得到剩余容量$C_{\\text{rem}}=C_{\\text{HBM}}-K-M$；再由$C_{\\text{rem}}$减去激活峰值$\\alpha\\cdot b$，得到可用于权重的容量$C_w$；最后$h=\\lfloor C_w/w\\rfloor$给出在当前批大小下能常驻的热点专家上限，$c$由剩余零头决定。若$h$低于热度表标记的热点集合大小，则二次路由必然频繁触发换入，此时应优先下调$b$或上调压缩档位$r$，而不是硬撑容量因子。这个顺序——先KV、再激活、后权重——对应D²MoE调度层“按KV水位下调批大小以守住尾延迟”的动作顺序，账本与调度逻辑是一致的。</p>\n<p>代入一组端侧量级：若$C_{\\text{HBM}}$为数十GB、$w$为数十MB、$h$为十余个专家，则热点权重占去数GB；$S=4096$、$b=8$时KV约2 GiB量级；激活峰值随$b$线性上升。剩余容量决定了$c$只能是个位数，意味着冷门专家换入是稀缺动作，必须由二次路由的收益判据严格把关。这就是为什么论文强调“限制重路由幅度”：在端侧账本里，$c$的每一次增加都是一次不可逆的带宽支出。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-21\">二十一 · 账本滞后与抖动：水位估计的工程边界</h3>\n<p>账本的所有输入都是估计值：热度表是滑动窗口统计，KV水位是块表读数，两者都有滞后。滞后直接进入容量因子决策：当长尾突变使某专家队列突然变长时，热度表尚未更新，调度层仍按旧$h$分配常驻权重，二次路由于是把溢出token重分配到低负载副本，触发一批换入；等到热度表追上，热点集合已变，刚换入的专家又变成冷门，形成来回搬运。D²MoE用“限制重路由幅度”抑制这种抖动，本质是给账本加一个变化率上限，使$c$的调整步长小于滞后窗口内的真实变化量。</p>\n<p>工程判断有三条。其一，KV水位的采样频率应高于热度表：块表读数是廉价的，而热度统计需要跨批聚合，两者时间常数不同，混在同一决策周期里会让批窗口对KV过冲、对热度欠调。其二，压缩档位的切换要有滞回区间，避免水位在档位边界附近反复压缩/解压，把带宽消耗在无收益的往返上。其三，换出决策应优先选“本批内已服务完毕且下批预测热度低”的专家，而不是单纯按当前计数排序——账本记的是过去，调度要的是下一批的可行性。这三条不改变D²MoE的机制框架，但决定了账本在真实端侧负载下是否可复算、可解释。</p>\n<p>最后落在具体机制上：D²MoE把容量因子变成运行时决策变量，其可行性完全依赖这本四账户账本的实时可读性。若块表与热度表的读数不能在同一调度周期内对齐，容量因子就会在“省显存”与“保尾延迟”之间震荡；因此端侧部署的第一件事不是调容量因子，而是把KV块水位、激活峰值系数$\\alpha$与专家权重字节数$w$标定成可复算的常量，让每一次批窗口收缩都有账可查。账本先立住，双路由的重分配才有稳定的兑换率可言。</p>\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-22\">二十二 · 批窗口与容量因子：把静态超参变成运行时决策变量</h3>\n<p>D²MoE 调度层最核心的动作，是把两个原本写死在部署配置里的量——批窗口（batch window）与容量因子（capacity factor）——提升为每个调度周期重新求解的决策变量。批窗口决定这一轮预填或解码接纳多少 token，容量因子决定每个专家在分组 GEMM 里预留多少槽位。传统做法取固定容量因子，例如按训练期专家负载均值乘以一个安全系数，端侧长尾请求一旦把某个专家打爆，溢出 token 只能排队或丢弃，尾延迟立刻抬升；反过来，为长尾预留过大容量因子又会在正常负载下浪费显存，挤占 KV 块空间。调度层的做法是维护两张表：专家热度表记录滑动窗口内每个专家的 token 到达率与队列长度，KV 块水位记录当前已分配块数、压缩档位与可换出余量；每个调度周期用这两张表加 SLO 预算联合决定批窗口大小与各专家容量因子。</p>\n<p>论文给出的代价函数把排队惩罚与显存代价放在同一个标量里：</p>\n<div class=\"formula\">$$\\text{cost}(b)=\\sum_{e}\\max\\left(0,\\frac{n_e(b)}{C_e}-1\\right)\\cdot L_e+\\lambda\\cdot\\text{KV}(b)$$</div>\n<p>这里 $n_e(b)$ 是批 $b$ 内路由到专家 $e$ 的 token 数，$C_e$ 是该专家的容量因子（槽位数），$L_e$ 是专家 $e$ 的单位排队代价（可由历史尾延迟敏感度校准），$\\text{KV}(b)$ 是批 $b$ 占用的 KV 块量，$\\lambda$ 是显存影子价格。第一项只在 $n_e&gt;C_e$ 时非零，度量溢出 token 的排队代价；第二项度量显存占用。调度层在每个周期对候选批窗口求解近似最小化，得到“这一轮该放多少 token、每个专家留多少槽”。关键在于 $C_e$ 不再是全局常数，而是随热度表逐专家调整：热点专家扩容，冷门专家缩容，缩出来的显存还给 KV 块。系统代价上，这直接改变显存碎片形态——固定容量因子下每个专家槽位等大，冷门专家占着不用的槽造成内部碎片；动态容量因子把槽位按热度重新分配，碎片从“每专家固定浪费”变成“按需浮动”，代价是调度层每周期多一次表查询与小规模求解，属于微秒到毫秒级开销，相对于端侧单设备一次预填的百毫秒量级可以忽略，但周期过短会引入抖动，因此需要与热度表的滑动窗口长度匹配。</p>\n<p>一个具体例子：长尾混合批次到达，短请求与长预填混排，热度表显示专家 $e_1$ 队列长度已超其当前 $C_{e_1}$，而 $e_7$、$e_9$ 队列近乎为空。调度层把 $C_{e_1}$ 上调、$C_{e_7}/C_{e_9}$ 下调，同时因 KV 水位尚低而放大批窗口；下一周期 KV 水位上升，$\\lambda$ 项变大，批窗口被压回，容量因子停止扩张。整个过程容量因子在运行时被反复重解，而不是部署期一次定死。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-23\">二十三 · 连续批处理与 chunked prefill：预填窗口按 SLO 预算切分</h3>\n<p>端侧 MoE 的预填阶段是显存与算力双重峰值：一次长预填的中间激活与 KV 写入同时抬升，若整段预填独占执行窗口，解码请求被完全阻塞，尾延迟由最长预填决定。D²MoE 采用 chunked prefill，把长预填按 SLO 预算切成若干 chunk，与解码 token 交错进入同一批窗口。切分粒度不是固定 token 数，而是由调度层按当前 KV 水位与专家热度决定：水位高时 chunk 切小，给解码让出显存；热度表显示热点专家排队时 chunk 也切小，避免一次 chunk 把某专家队列进一步堆高。连续批处理（continuous batching）在此之上做迭代级调度——每个解码步结束即重排批内请求，完成的请求退出、新到达的请求插入，批组成随迭代变化，而不是等整批跑完再换。</p>\n<p>伪代码思路可写成：调度周期开始时读取热度表与 KV 水位，按 SLO 预算选出本轮预填 chunk 长度 $l_p$ 与解码并发数 $n_d$，满足 $l_p\\cdot \\bar{a}_p+n_d\\cdot \\bar{a}_d\\le$ 本轮算力预算且 KV 增量不超水位余量；然后按专家分组聚合本轮所有 token 做分组 GEMM。这里 $\\bar{a}_p$、$\\bar{a}_d$ 分别是预填与解码的每 token 平均算力开销，材料未给出具体数值，工程上由离线校准得到。系统代价体现在两个方向：chunk 切得越细，解码尾延迟越可控，但预填的固定开销（每次 chunk 启动的分组聚合、权重读取）被摊薄得越差，预填吞吐下降；chunk 切得越粗，预填吞吐好，但解码被长时间阻塞，尾延迟抬升。D²MoE 的取舍点由 SLO 预算而非固定阈值决定，这是它与固定 chunk 策略的关键差别。</p>\n<p>具体例子：一个长预填请求与若干短解码请求同时到达，固定策略下长预填整段执行，解码请求等它跑完，尾延迟被拉长到预填时长量级；D²MoE 把预填切成多个 chunk，每个 chunk 之间插入一轮解码迭代，解码请求的 token 间隔被压到 chunk 时长量级，尾延迟显著下降，代价是预填总时长因交错而略增。预填与解码共享专家权重但分时复用，意味着两者不能真正并行占用同一份权重，交错执行正好匹配这一约束——权重只驻留一次，预填 chunk 与解码迭代轮流使用，避免了两份权重副本的显存开销。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-24\">二十四 · 优先级与抢占：热点专家队列作为准入信号</h3>\n<p>端侧单设备的并发能力有限，调度层必须决定谁先执行、谁被推迟、谁被抢占。D²MoE 把热点专家队列长度当作准入与抢占的触发信号：当某专家队列超过其容量因子，新到 token 若仍路由到该专家，要么被二次路由重分配（见路由层），要么在调度层被降优先级推迟。优先级不是按请求到达顺序，而是按“该请求本轮是否会加剧热点排队”来定——一个路由分布集中在热点专家的请求，其优先级低于路由分布分散的请求，因为前者会进一步堆高 $n_e/C_e$ 的溢出项。抢占则发生在 KV 水位逼近上限时：调度层选择 KV 占用大且已生成部分 token 的请求，将其 KV 块压缩或换出，腾出空间给高优先级请求，被抢占请求在稍后恢复。</p>\n<p>代价函数中的排队项直接给出抢占判据：若某请求加入后使 $\\sum_e\\max(0,n_e/C_e-1)L_e$ 的增量超过其带来的吞吐收益（以 $\\lambda\\cdot\\text{KV}$ 折算），则推迟或抢占它更划算。系统代价是抢占带来的重算：被换出的 KV 块恢复时需要重新读入，若压缩有损还需重算部分注意力，端侧带宽有限时这笔开销不可忽略。因此 D²MoE 限制抢占幅度——只在 KV 水位越过档位阈值时触发，且优先换出冷门专家的权重而非热点请求的 KV，形成“热点专家权重常驻、冷门专家按需换入”的显存折中。具体例子：解码阶段 KV 水位上升，调度层先把冷门专家 $e_7$ 的权重换出，腾出的显存给 KV 块；若水位仍高，才对低优先级长请求做 KV 块压缩，压缩比例按水位分档设定。这一顺序保证热点路径上的请求不被无谓打断，尾延迟主要由热点专家排队而非抢占重算决定。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-25\">二十五 · 分离式预填/解码在单设备上的映射</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）在云端通常指预填与解码跑在不同 GPU 池上，通过 KV 传输解耦两阶段的资源竞争。端侧单设备没有多池可分，D²MoE 把它映射为时间维度的分离：预填与解码共享同一份专家权重，但按 SLO 预算分配执行窗口，分时复用而非空间分离。调度层为预填保留固定比例的执行窗口（由 SLO 预算与当前队列长度决定），解码在剩余窗口内以连续批处理推进；当预填队列积压时窗口比例上调，当解码尾延迟逼近 SLO 时窗口回调。这与 chunked prefill 的区别在于粒度：chunked prefill 是迭代级交错，窗口分配是周期级的资源配额，两者叠加形成“周期配额 + 迭代交错”的两级结构。</p>\n<p>这种映射的系统代价是窗口切换的上下文开销：每次从预填切到解码，分组 GEMM 的专家分组要重建，热度表要更新，权重虽常驻但分组元数据需重排。窗口切得太频繁，切换开销吃掉收益；切得太粗，两阶段资源竞争回归。D²MoE 用 SLO 预算约束窗口长度下限，避免过频切换。容量规划上，这一映射给出一条可迁移的判断：单设备上预填/解码的“分离”本质是执行窗口的配额分配，配额由尾延迟约束反推，而不是由吞吐最大化决定；若把云端分离式部署的容量公式直接套到端侧，会忽略权重共享带来的显存约束，导致配额偏大、KV 溢出。具体例子：一个以短请求为主、偶发长预填的负载，窗口配额应偏向解码，预填窗口只需覆盖长预填的 chunk 切分需求；反之长预填密集的负载，窗口配额偏向预填，解码靠 chunk 间空隙推进，尾延迟由 chunk 时长而非窗口长度决定。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-26\">二十六 · 尾延迟怎么压：三个闭环与一个抖动约束</h3>\n<p>尾延迟在端侧 MoE 上由三个来源叠加：热点专家排队、KV 水位触发的换出/压缩重算、预填阻塞解码。D²MoE 对应三个闭环：路由闭环用二次路由把溢出 token 移出热点专家，直接削 $n_e/C_e$ 的溢出项；显存闭环用 KV 水位驱动压缩档位与冷门专家换出，压低 $\\lambda\\cdot\\text{KV}$ 项并避免溢出；调度闭环用批窗口与 chunk 切分控制预填对解码的阻塞时长。三个闭环共享热度表与水位表，但更新频率不同——路由闭环逐批更新，显存闭环按水位档位跳变更新，调度闭环按 SLO 预算周期更新。频率不一致是抖动的根源：热度表滞后于真实路由分布时，二次路由可能把 token 从一个即将变热的专家移走，下一周期又移回，形成批内路由抖动。</p>\n<p>论文对此的约束是限制重路由幅度：单次二次路由移走的 token 比例设上限，且触发信号必须是热点专家队列超容量因子而非仅热度表读数偏高。工程判断上，这个上限应与滑动窗口长度联动——窗口越长，热度估计越平滑但滞后越大，重路由幅度上限应越小以抑制抖动；窗口越短，估计越灵敏但噪声越大，上限同样不能放宽。尾延迟的压低因此不是靠单点激进调度，而是靠三个闭环在各自时间尺度上小步修正。具体例子：长尾突变到来，某专家队列瞬间超容量因子，二次路由按幅度上限移走部分溢出 token，剩余 token 排队；下一周期热度表更新，容量因子上调吸收队列，重路由回撤。若没有幅度上限，第一周期可能把过多 token 移走，第二周期又大量移回，批内专家分布反复横跳，分组 GEMM 的分组规模剧烈变化，反而抬高尾延迟。这一机制把“压尾延迟”从单次调度决策变成带阻尼的反馈控制，代价是收敛速度略慢于无约束重路由，但避免了抖动带来的长尾尖峰。</p>\n<p>把三个闭环合起来看，D²MoE 在端侧单设备上的调度本质是：用热度表与 KV 水位两张低维状态表，把容量因子、批窗口、chunk 粒度、重路由幅度四个量绑在一个带阻尼的反馈环里，代价函数 $\\text{cost}(b)$ 提供统一的取舍标量。它的局限也在这里——两张表的估计滞后在长尾突变下无法消除，单设备结论不能直接外推到多设备专家并行；但把容量因子从静态超参变为运行时决策变量、把专家热度与 KV 水位纳入批调度闭环这一工程路径，对有限显存下的尾延迟控制有直接参考价值，并可迁移到分离式预填/解码的容量规划：配额由尾延迟约束反推，而非吞吐最大化。</p>\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-27\">二十七 · 切分维度：为什么端侧单设备也要谈 TP/EP/PP/DP</h3>\n<p>D²MoE 的正文把并行拓扑限定在单设备内专家分组执行，未涉及跨设备专家并行与 All-to-All，这一点在材料里写得很清楚。但工程读者真正要问的是：既然论文只做单卡，为什么并行与通信这一节仍然必须写？原因是端侧 MoE 的“并行”并未消失，只是被压缩到了同一块 SM100/SM103 内部——TP 变成张量切分后的 warp-group 协作，EP 退化为专家分组 GEMM 的 token 重排，PP 退化为预填与解码的分时复用，DP 退化为多副本专家在显存中的并存。四者的通信代价从跨机 NVLink 5 与 NVSwitch 的域内 All-to-All，降级为 SMEM/TMEM 搬运与 L2 命中，但代价结构同构：谁搬运的字节多，谁就先撞上带宽墙。</p>\n<p>把四种切分放到一张表里看，端侧与云端的差别不在语义而在量级。云端 EP 的 All-to-All 走 NVLink 5，单链路带宽远高于 PCIe，NVSwitch 提供全互联无阻塞交换；端侧没有 NVSwitch，专家副本之间的“重分配”实际是同一显存内的地址跳转与分组索引重写，代价从网络字节变成显存读写与索引构造。D²MoE 的二次路由正是利用这一点：把热点专家溢出 token 重分配到低负载副本，在单设备上等价于一次 token 索引的重新分组，不需要跨设备通信，但会引入额外的 gather/scatter 与分组 GEMM 的启动开销。</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>云端形态</th><th>端侧 D²MoE 形态</th><th>主要代价</th></tr></thead><tbody><tr><td>TP</td><td>层内张量切分 + All-Reduce</td><td>warp-group 内分块，TMEM 累加</td><td>SMEM 带宽、同步屏障</td></tr><tr><td>EP</td><td>专家分片 + All-to-All</td><td>专家分组 GEMM + 索引重排</td><td>显存读写、分组启动</td></tr><tr><td>PP</td><td>层间流水 + 点对点</td><td>预填/解码分时复用权重</td><td>权重换入换出、KV 水位</td></tr><tr><td>DP</td><td>副本并行 + 梯度/激活同步</td><td>冷热专家副本并存</td><td>显存占用、换入延迟</td></tr></tbody></table>\n<p>这张表的意义在于给出判断依据：当端侧 EP 的重排字节数超过分组 GEMM 节省的算力时，二次路由就从收益变成负担。D²MoE 用重路由幅度限制来约束这一点，长尾突变下不允许无限重分配，避免批内路由抖动——抖动本身就是一种通信代价，因为每次重排都要重建分组索引。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-28\">二十八 · All-to-All 与 All-Reduce 的代价公式：通信何时压过计算</h3>\n<p>判断通信是否成为瓶颈，标准做法是算“计算-通信比”。对一次专家分组的 All-to-All，单 token 需搬运的字节数为 $k \\cdot d \\cdot s$，其中 $k$ 为 top-k、$d$ 为隐藏维、$s$ 为每元素字节数；分组 GEMM 的有效算力为 $2 \\cdot k \\cdot d \\cdot d_{ff}$ 次浮点运算。于是通信时间与计算时间之比可写成：</p>\n<div class=\"formula\">$$\\rho=\\frac{k\\cdot d\\cdot s/B_{\\text{link}}}{2\\cdot k\\cdot d\\cdot d_{ff}/F_{\\text{sm}}}=\\frac{s\\cdot F_{\\text{sm}}}{2\\cdot d_{ff}\\cdot B_{\\text{link}}}$$</div>\n<p>公式里 $k$ 被约掉，这说明一个反直觉的结论：All-to-All 的相对代价与 top-k 无关，只与元素字节、算力、专家中间维和链路带宽有关。端侧 $B_{\\text{link}}$ 是显存带宽而非 NVLink，$F_{\\text{sm}}$ 是单设备算力，$\\rho$ 往往显著大于云端——这正是端侧 MoE 必须做分组聚合而非逐 token 搬运的根本原因。D²MoE 的执行层按专家分组聚合 token 再做分组 GEMM，把多次小搬运合并为一次大搬运，等价于把公式中的 $B_{\\text{link}}$ 有效利用率抬高。</p>\n<p>All-Reduce 的代价则是另一条曲线。TP 切分下每层一次 All-Reduce，搬运量为 $2(N-1)/N \\cdot d \\cdot s$，$N$ 为切分数。端侧 $N$ 很小甚至为 1，All-Reduce 退化为 TMEM 内的累加与 SMEM 回写，代价从网络字节转为片上带宽。但 tcgen05 的 2-SM MMA 让两个 SM 协作完成一次矩阵乘，跨 SM 的 TMEM 访问成为新的同步点——这不是网络通信，却同样遵循“搬运字节除以带宽”的代价模型。工程判断是：端侧 TP 的瓶颈不在 All-Reduce 本身，而在 MMA 完成后的累加结果回写与下一次 MMA 的依赖屏障。</p>\n<p>具体例子：一个 top-k=2、隐藏维 4096、专家中间维 14336 的层，若逐 token 做专家分发，每次搬运 2×4096×2 字节（FP16），分组后一次搬运整批 token 的同一专家切片，搬运次数从批大小量级降到专家数量级。代价从“批大小 × 单 token 字节”变为“专家数 × 专家切片字节”，在批较大时后者显著更省，但批较小时分组启动开销占主导——这就是 D²MoE 调度层要动态决定批窗口的原因，批窗口太小则分组不划算，太大则 KV 水位吃紧。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-29\">二十九 · NVLink 5、NVSwitch 与 NIXL：跨设备时的通信骨架</h3>\n<p>把视角抬到 GB200/GB300 NVL72，通信骨架由三层构成：NVLink 5 提供 GPU 间高带宽直连，NVSwitch 提供机柜内全互联无阻塞交换，NIXL 提供推理侧的异步点对点传输抽象，用于 KV cache 与激活的跨节点搬运。对分离式预填/解码，NIXL 承担的是预填节点向解码节点传送 KV 块的任务，传输量与 KV 块大小、并发请求数成正比；对 EP，All-to-All 走 NVSwitch，通信模式是“每个 GPU 向所有 GPU 发送其负责专家的 token 子集”，代价随专家分片数与 token 数增长。</p>\n<p>通信何时成为瓶颈，可以用一个可操作的判据：当单层 All-to-All 时间超过该层分组 GEMM 时间时，EP 就不再划算。前者由 $k \\cdot d \\cdot s \\cdot N_{\\text{peer}}/B_{\\text{nvlink}}$ 决定，后者由 $2 \\cdot k \\cdot d \\cdot d_{ff}/F_{\\text{sm}}$ 决定。NVL72 的 NVSwitch 把 $N_{\\text{peer}}$ 增大带来的阻塞压低，但 All-to-All 的字节数仍随 $N_{\\text{peer}}$ 线性增长，因此大规模 EP 的瓶颈往往不在链路带宽而在交换机端口的总吞吐与拥塞控制。D²MoE 的单设备结论不能直接外推到这一层，材料也明确说跨设备扩展性未讨论——工程上必须把单设备的“分组重排”与多设备的“All-to-All”分开建模，不能把前者的收益直接搬到后者。</p>\n<p>NIXL 的代价模型更接近流水线：传输时间 = KV 块字节 / 有效带宽 + 固定握手开销。分离式部署中，预填与解码的算力配比决定了 KV 传输是否成为端到端瓶颈；若解码侧算力不足而预填侧过剩，KV 传输会被解码消费速度反向压制，此时增加预填并行度无益。这与 D²MoE 调度层用 KV 水位决定批窗口是同构的判断：水位高则压缩与换出，水位低则扩批。区别在于端侧换出到主机内存，跨节点则是走 NIXL 到另一台机器，后者延迟高一个量级，因此跨节点场景下 KV 水位阈值必须更保守。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-30\">三十 · 通信与调度的耦合：重路由幅度就是通信预算</h3>\n<p>D²MoE 的二次路由在单设备上不产生网络通信，但产生显存侧的重排代价。把重路由幅度记为 $\\delta$，即被重新分配的 token 比例，则额外代价可写成：</p>\n<div class=\"formula\">$$\\text{cost}_{\\text{reroute}}=\\delta\\cdot n\\cdot d\\cdot s\\cdot\\alpha+\\beta\\cdot G$$</div>\n<p>其中 $\\alpha$ 是重排的每字节代价系数，$G$ 是分组数，$\\beta$ 是每组启动开销。第一项随重路由比例线性增长，第二项随分组数增长。调度层限制 $\\delta$ 的上界，本质是在给通信预算封顶：允许重路由削平热点队列，但不允许重排字节吞掉分组 GEMM 的收益。这个上界由校准集上的尾延迟约束确定，属于部署期参数，运行时只做滑动窗口内的微调。</p>\n<p>耦合点还在于预填与解码的分时复用。预填阶段 token 多、分组大，重排摊薄到每个 token 的代价低；解码阶段逐 token 路由，批内专家分布快速漂移，重排比例虽小但分组启动开销占比高。因此同一 $\\delta$ 上界在两个阶段应有不同取值，D²MoE 用 SLO 预算切分预填窗口正是为此：把重排密集的操作尽量放在预填窗口内完成，解码窗口只做必要的溢出重分配。代价是预填窗口被拉长会挤占解码的算力窗口，尾延迟约束下两者存在此消彼长。</p>\n<p>具体例子：某批次热点专家队列超容量因子，二次路由把溢出 token 重分配到低负载副本。若溢出比例为 10%，重排字节为 $0.1 \\cdot n \\cdot d \\cdot s$，在显存带宽受限的端侧设备上，这部分字节与分组 GEMM 的权重读取争抢同一带宽。调度层的做法是把重排与分组 GEMM 错峰：先完成重排索引构造，再启动分组 GEMM，避免两者同时占用带宽。这是用时间换带宽的典型手法，代价是流水线气泡，气泡长度由索引构造时间决定。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-31\">三十一 · 失败模式与工程判据：什么时候不该并行</h3>\n<p>通信成为瓶颈的判据可以归纳为三条可观测信号。第一，分组 GEMM 的 SM 利用率因等待重排索引而下降，说明重排与计算未错峰；第二，KV 水位触发的换出与专家换入在同一时间窗内叠加，说明显存带宽被双向争抢；第三，尾延迟随批大小增大而恶化而非改善，说明批窗口已越过通信-计算平衡点。D²MoE 的调度层维护专家热度表与 KV 水位，正是为了在运行时捕捉这三条信号并调整批窗口与容量因子。</p>\n<p>失败模式在材料里写得很直接：热度表与 KV 水位估计存在滞后，长尾突变下重路由可能抖动。抖动的代价是反复重建分组索引，等价于把通信预算浪费在无效重排上。工程上的缓解手段是给重路由加滞回区间：队列长度超过容量因子一定比例才触发，回落到另一阈值以下才停止，避免在边界反复横跳。这与云端 EP 的拥塞控制思路一致，只是端侧的“拥塞”发生在显存而非交换机端口。</p>\n<p>另一条判据关于并行拓扑的选择：端侧单设备上 TP 切分数不宜过大，因为 2-SM MMA 的跨 SM 同步与 TMEM 回写会吃掉切分收益；EP 的专家副本数受显存约束，冷门专家按需换入意味着副本并存不是免费的；PP 的分时复用要求预填与解码共享权重，权重换入的延迟必须小于窗口切换的收益。D²MoE 的创新点之一正是把这三者的取舍交给调度层动态决定，而不是在部署期一次性固定。容量因子从静态超参变为运行时决策变量，本质上是把并行拓扑的通信预算也变成了可调参数。</p>\n<p>最后落到一个具体机制上：当调度层检测到热点专家队列超容量因子且 KV 水位同时上升时，它优先下调批大小而非扩大重路由幅度。原因是扩大重路由会引入重排字节，而下调批大小只减少分组 GEMM 的规模，前者争抢带宽，后者释放带宽。这个优先级顺序是端侧显存受限场景下的工程判断，与云端“扩容优先”的直觉相反——端侧没有多余的链路带宽可以挥霍，任何重排都必须先证明自己比缩小批次更划算。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-32\">三十二 · 并行拓扑的边界：单设备分组执行与跨设备扩展的代价断层</h3>\n<p>D²MoE 的执行层拓扑是单设备内的专家分组执行，材料明确未涉及跨设备专家并行与 All-to-All。这一点决定了本方案的通信代价结构：分组 GEMM 的聚合发生在同一设备的 HBM 与 SM 之间，token 从门控输出到专家分组的重排是片上数据搬运，不经过 NVLink。换言之，D²MoE 用“专家分组 + 分时复用”换掉了 EP 的 All-to-All，代价是把并行度锁死在单设备算力与带宽上。一旦要把这套机制推到 GB200 NVL72 这类机柜级拓扑，二次路由的“低负载副本”就必须落在远端 GPU 上，溢出 token 的重分配立刻变成一次 All-to-All 或 NIXL 传输，路由决策的目标函数也要从“队列长度”扩展为“队列长度 + 链路拥塞”。此时重路由的收益必须与通信代价对账：设重路由把 $m$ 个 token 从热点专家 $e_h$ 迁到副本 $e_r$，省下的排队时间为 $\\Delta q$，而跨设备搬运代价为 $m \\cdot s \\cdot \\tau$（$s$ 为单 token 激活字节数，$\\tau$ 为单位字节传输时间），只有当 $\\Delta q &gt; m s \\tau$ 时重路由才划算。在 NVLink 5 与 NVSwitch 全互联下 $\\tau$ 很小，但 All-to-All 的集合通信同步开销随参与 rank 数上升，端侧单设备的“零通信”优势在多设备上不复存在。</p>\n<p>通信何时成为瓶颈，取决于三个量的相对大小：单 token 激活的字节数、专家并行的跨度、以及批窗口内 token 的分布偏斜度。All-to-All 的通信量近似为 $V_{\\text{a2a}} \\approx B \\cdot k \\cdot s \\cdot (1 - h)$，其中 $B$ 为批内 token 数、$k$ 为 top-k、$h$ 为命中本地专家的比例；$h$ 越高通信越少。D²MoE 的负载感知二次路由本质上是在单设备内把 $h$ 推向 1，而在多设备 EP 下它反而可能主动降低 $h$ 以削平远端热点，这是一对方向相反的力。All-Reduce 在 TP 切分下则是另一条路径：TP 的每层都要做激活的 All-Reduce，通信量与隐藏维度成正比、与 TP 度成正比，延迟敏感的解码阶段尤其吃亏——解码每步只算一个 token，计算量小到无法掩盖 All-Reduce 的固定同步开销，于是 TP 在解码阶段常被通信主导，而预填阶段因计算密度高反而能掩盖。这正是分离式预填/解码在并行策略上要分开配置的原因：预填偏 TP、解码偏 EP 或 DP 复制。</p>\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>通信原语</th><th>瓶颈阶段</th><th>与 D²MoE 的关系</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce</td><td>解码（计算无法掩盖同步）</td><td>材料未涉及，单设备内无此开销</td></tr><tr><td>EP</td><td>All-to-All（两次）</td><td>预填与解码均受 $h$ 支配</td><td>二次路由跨设备化的直接代价</td></tr><tr><td>PP</td><td>点对点激活传递</td><td>流水气泡，微批划分</td><td>与分时复用窗口冲突</td></tr><tr><td>DP</td><td>梯度/权重同步（推理侧无）</td><td>无</td><td>副本复制可替代重路由</td></tr></tbody></table>\n<p>把 D²MoE 的调度闭环外推到多设备，会暴露一个滞后放大问题：热度表是滑动窗口统计，单设备上窗口延迟只影响本机批窗口；在 EP 拓扑下，热度表的更新还要跨 rank 汇聚，汇聚本身走 All-Reduce 或 NIXL，窗口延迟被通信往返拉长，二次路由的触发信号（队列超容量因子）到达时热点可能已经转移。此时限制重路由幅度不只是防抖动，更是防“用一次昂贵的 All-to-All 去追一个已经消失的热点”。NIXL 在这里的角色是把 KV 块与冷门专家权重的换出从设备内 HBM 扩展到跨节点存储层级，但它的传输是异步的、带宽受限于后端存储，KV 压缩档位的切换若与 NIXL 换出耦合，尾延迟会出现由传输队列深度决定的二次抬升——这是单设备材料中“KV 按水位分档”所没有的新代价项。</p>\n<p>工程判断落在容量规划的口径上：D²MoE 的 $\\text{cost}(b)$ 公式只含专家排队与 KV 占用两项，跨设备部署时必须加入第三项通信惩罚 $\\gamma \\cdot V_{\\text{a2a}}(b)$，且 $\\gamma$ 随拓扑变化——NVLink 5 全互联下小、跨机柜或经 NIXL 落盘时大。若 $\\gamma$ 大到使重路由的边际收益为负，正确做法不是加大重路由幅度，而是改用 DP 副本复制：把热点专家的权重整体复制到多个设备，让路由在本地命中，用显存换通信。这与 D²MoE“热点专家权重常驻、冷门按需换入”的显存折中同构，只是把折中的维度从单设备 HBM 水位换成了跨设备权重副本数与链路带宽的比值。材料未给出量化精度与分组 GEMM 底层细节，因此跨设备扩展后的数值收益无法核验，但拓扑代价的结构是确定的：单设备的零通信是这套双路由机制最锋利的边界，也是它最难平移的部分。</p>\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-33\">三十三 · 精度塌陷：从“数值可疑”到“语义崩坏”的分级诊断</h3>\n<p>端侧MoE的精度塌陷很少是单一原因，而是“路由决策漂移 + 数值格式误差 + 分组GEMM聚合顺序”三者叠加。D²MoE的二次路由把热点专家溢出token重分配到低负载副本，这一动作在数值上等价于改变了token的专家归属，若重路由阈值过松，同一token在不同批窗口里可能落到不同专家，输出分布随之抖动。诊断时不能只看最终困惑度，要建立三级信号：第一级是门控置信度分布，token级top-k门控输出的置信度若在重路由前后出现系统性偏移，说明二次路由正在改写语义路径；第二级是分组GEMM的累加误差，按专家聚合token时，同一专家的token若来自不同批窗口，累加顺序变化会放大低精度格式的舍入偏差；第三级才是任务指标，即长尾请求的答案一致性。工程上把这三级的监控点挂在路由层出口和执行层写回处，用滑动窗口统计置信度均值与方差，方差突增即触发告警。代价上，精度塌陷的隐性成本是重试与人工介入，端侧单设备没有云端的多副本冗余，一次塌陷往往意味着整个批窗口的响应作废，尾延迟直接翻倍。</p>\n<div class=\"formula\">$$\\Delta_{\\text{conf}}=\\left|\\mathbb{E}[\\text{conf}_{\\text{post}}]-\\mathbb{E}[\\text{conf}_{\\text{pre}}]\\right|,\\quad \\text{alert if }\\Delta_{\\text{conf}}&gt;\\tau_{\\text{conf}}$$</div>\n<p>具体例子：一个长尾混合批次中，短请求与长预填同时到达，热度表显示某专家队列超容量因子，二次路由把溢出token重分配到低负载副本。若该副本的权重常驻状态与热点专家不同（冷门专家按需换入），换入过程中的权重加载可能引入额外的量化截断，导致这批token的输出与未重路由时不一致。定位方法是把重路由前后的token分别走一遍离线校准集，比较置信度偏移与答案一致性，若偏移集中在特定专家副本，则问题在换入路径而非门控本身。回滚手段是把二次路由阈值临时收紧到校准集尾延迟约束下的保守值，让溢出token排队而非重分配，用尾延迟换精度稳定。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-34\">三十四 · OOM与显存碎片：水位监控与换出策略的失效点</h3>\n<p>端侧OOM不是“显存不够”这么简单，D²MoE的显存账本由三部分组成：常驻热点专家权重、按需换入的冷门专家权重、以及按块压缩与换出的KV cache。调度层维护KV块水位，按水位分档压缩与换出，但水位估计存在滞后——解码阶段逐token路由使批内专家分布快速漂移，KV占用在几个token内就可能跳档。OOM的典型触发路径是：批窗口按SLO预算切分时容量因子偏大，预填阶段一次性写入大量KV块，水位监控还没来得及触发压缩，下一个解码步的专家换入又申请了额外显存，两者叠加越过硬上限。诊断要看三个量：KV块水位的变化速率、专家换入的申请频率、以及批窗口内容量因子的实际使用率。若水位速率与换入频率同时上升而容量因子使用率低于阈值，说明是碎片而非真实需求导致的OOM。</p>\n<div class=\"formula\">$$\\text{headroom}(t)=M_{\\text{total}}-\\sum_{e\\in\\text{hot}}W_e-\\sum_{e\\in\\text{cold}}W_e\\cdot\\mathbb{1}_{\\text{resident}}-\\text{KV}(t)$$</div>\n<p>具体例子：解码阶段KV水位上升触发块压缩与冷门专家换出，但压缩比例按显存水位分档设定，档位切换有延迟。若批内突然出现一批长尾请求，KV块在档位切换前已写满，换出动作来不及执行，OOM发生。定位方法是把OOM时刻的专家热度表与KV水位快照对齐，看是哪个专家的换入申请与KV写入撞在同一时间窗。回滚策略是下调批窗口上限并提高压缩档位，把容量因子从运行时决策变量临时退回校准集初值，牺牲吞吐守住显存。代价上，OOM的恢复不是免费的：端侧单设备重启推理进程意味着权重重新常驻，热点专家权重的加载时间直接计入尾延迟。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-35\">三十五 · 批抖动：容量因子动态调整的振荡与收敛</h3>\n<p>批抖动是D²MoE动态调度最典型的失败模式。容量因子从静态超参变为运行时决策变量，调度层按专家热度与KV水位调整批窗口，但热度表用滑动窗口统计在线更新，存在固有滞后。当长尾突变发生时，热度表还没来得及反映新分布，调度层已经按旧热度放大了批窗口，热点专家队列瞬间超容量因子，二次路由把溢出token重分配，下一窗口热度表更新后又把批窗口收回，形成“放大—重路由—收回”的振荡。抖动的代价不是单次延迟，而是批内token的专家归属反复变化，分组GEMM的聚合模式随之反复切换，执行层的分组开销被放大。诊断批抖动要看批窗口大小的自相关函数与重路由触发频率：若批窗口在相邻窗口间反复跳变且重路由频率与跳变同相，即为振荡。</p>\n<div class=\"formula\">$$b_{t+1}=b_t+\\alpha\\left(\\hat{h}_t-h^\\star\\right)-\\beta\\left(\\text{KV}_t-\\text{KV}^\\star\\right),\\quad \\text{clip}(b_{t+1},b_{\\min},b_{\\max})$$</div>\n<p>具体例子：一个长尾混合请求批次，调度层先按SLO预算切出预填窗口，热度表显示某专家队列超容量因子，二次路由重分配溢出token，批大小随KV水位下调。若下调幅度过大，下一窗口解码阶段专家分布漂移，热度表更新后批窗口又上调，热点专家再次排队。定位方法是在调度层记录每次批窗口调整的触发信号（热度超限还是水位超限），统计两类信号的交替频率。回滚手段是限制重路由幅度——论文明确指出长尾突变下需限制重路由幅度避免批内路由抖动——把单次重路由的token比例设上限，并给批窗口调整加阻尼系数，用收敛速度换稳定性。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-36\">三十六 · 尾延迟：SLO预算被谁吃掉</h3>\n<p>尾延迟的恶化在D²MoE里通常不是单点慢，而是预填与解码的资源竞争。执行层让预填与解码共享专家权重但分时复用，按SLO预算分配执行窗口，这个分时复用的切换点就是尾延迟的敏感区。预填窗口切得长，解码请求排队；预填窗口切得短，预填token被拆成多次执行，分组GEMM的启动开销累积。调度层的SLO预算约束的是尾延迟，但预算的分配依据是专家热度表与KV水位，这两个量都有滞后，导致预算在突变时分配错位。诊断尾延迟要把请求按长度分桶，看长预填请求与短解码请求的P99是否在同一时间窗内同时抬升——若是，问题在分时复用的切换策略而非单请求执行。</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{tail}}=\\max_{r\\in\\text{batch}}\\left(T^{\\text{pre}}_r+T^{\\text{dec}}_r\\right),\\quad \\text{subject to } \\text{KV}(t)\\le M_{\\text{kv}}^{\\max}$$</div>\n<p>具体例子：热点专家权重常驻、冷门专家按需换入，一个长尾请求恰好路由到正在换入的冷门专家，换入等待时间直接计入该请求的尾延迟。若此时预填窗口正在执行，解码请求的专家换入被推迟，尾延迟进一步放大。定位方法是把每个请求的专家命中状态（常驻/换入）与等待时间关联，看尾延迟是否集中在换入路径。回滚策略是把SLO预算从尾延迟约束临时放宽到均值约束，优先保证批窗口稳定，等热度表收敛后再收紧。代价是SLO达成率的短期下降，但避免了抖动扩散到整个批。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-37\">三十七 · 静默降级：没有报错的质量流失</h3>\n<p>静默降级是端侧MoE最难诊断的失败模式：系统不报错、不OOM、不超时，但输出质量在缓慢流失。D²MoE的三个机制都可能贡献静默降级：二次路由把token重分配到低负载副本，副本的权重常驻状态不同，换入路径的量化截断在单token上不可见，累积到批级别才显现；KV块按水位分档压缩，压缩比例切换时旧块与新块的精度不一致，长上下文请求的注意力被悄悄改写；容量因子动态调整让批窗口内的专家分组频繁变化，分组GEMM的聚合顺序变化在低精度格式下引入舍入偏差。这些都不触发告警，因为监控项只覆盖专家热度表、KV水位、批大小与尾延迟，没有覆盖输出分布本身。诊断静默降级需要建立输出侧的基线：用离线校准集固定一批请求，定期重放并比较输出分布的散度，散度超过阈值即判定降级。</p>\n<div class=\"formula\">$$D_{\\text{KL}}\\left(p_{\\text{ref}}\\,\\|\\,p_{\\text{run}}\\right)=\\sum_{v}p_{\\text{ref}}(v)\\log\\frac{p_{\\text{ref}}(v)}{p_{\\text{run}}(v)}$$</div>\n<p>具体例子：KV压缩比例按显存水位分档设定，水位从低档跳到高档时，已写入的KV块被重新压缩，压缩后的块与未压缩块在同一注意力计算中混合，长上下文请求的输出出现细微偏移。单条请求看不出来，但同一请求在压缩前后重放的KL散度会抬升。定位方法是在KV压缩档位切换点打标记，把切换前后的请求分组比较散度。回滚手段是把压缩档位切换改为批边界触发而非水位即时触发，让同一批内的KV块保持同一精度档，用显存峰值换输出一致性。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-38\">三十八 · 监控闭环与回滚的工程判断</h3>\n<p>把上述失败模式收进一个可操作的闭环，需要监控项覆盖路由、调度、执行三层，并且每个监控项都要有对应的回滚动作。路由层监控门控置信度偏移与重路由token比例，回滚动作是收紧重路由阈值；调度层监控批窗口自相关与容量因子使用率，回滚动作是加阻尼或退回校准初值；执行层监控KV水位速率、专家换入频率与输出散度，回滚动作是切换压缩档位触发时机或固定专家常驻集。关键工程判断是：回滚不是回到静态配置，而是回到上一个稳定窗口的运行时参数快照。D²MoE把容量因子从静态超参变为运行时决策变量，这个设计的好处是灵活，代价是失败时没有天然的安全锚点，所以必须在调度层维护参数快照环，每个批窗口结束时写入当前容量因子、批窗口上限与压缩档位，异常时回退到最近一个尾延迟达标的快照。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要监控信号</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷</td><td>门控置信度方差</td><td>重路由前后token重放比对</td><td>收紧二次路由阈值</td></tr><tr><td>OOM</td><td>KV水位速率与换入频率</td><td>OOM时刻热度表与水位快照对齐</td><td>下调批窗口、提高压缩档位</td></tr><tr><td>批抖动</td><td>批窗口自相关与重路由频率</td><td>调度层触发信号交替统计</td><td>限制重路由幅度、加阻尼</td></tr><tr><td>尾延迟</td><td>分桶P99与专家命中状态</td><td>换入等待时间关联分析</td><td>放宽SLO预算至均值约束</td></tr><tr><td>静默降级</td><td>输出分布KL散度</td><td>压缩档位切换点分组比较</td><td>压缩切换改为批边界触发</td></tr></tbody></table>\n<p>这张表的核心不是列出五个名字，而是把每个失败模式绑到一个可执行的信号和一个可逆的动作上。端侧单设备的约束决定了回滚必须是批粒度的：不能像云端那样摘掉一个副本，只能在下一个批窗口切换参数。因此监控的采样频率要跟批窗口对齐，而不是跟token对齐——token级监控的开销会吃掉双路由本就不宽裕的算力预算。论文的材料没有给出量化精度方案与具体吞吐数字，这意味着静默降级的输出散度阈值只能靠离线校准集的经验分布来定，部署期参数而非训练目标。工程判断落在这一点：D²MoE的动态调度把容量因子变成运行时变量，收益是尾延迟与显存碎片的削减，代价是失败模式从“配置错误”变成了“控制回路失稳”，诊断与回滚的重心必须从查配置转向查回路。</p>\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-39\">三十九 · 基准口径的三层结构：模型档、设备档、负载档</h3>\n<p>读 D²MoE 这类端侧 MoE 推理工作，第一件事不是看它比谁快，而是先把“基准”拆成三层：模型档（哪个 MoE 模型、多少专家、top-k 取几、专家粒度多粗）、设备档（单设备显存容量、内存带宽、算力峰值、功耗墙）、负载档（请求长度分布、并发到达率、SLO 约束形态）。三层任何一层换了，数字就不能横向比。论文材料明确只给出“单设备端侧、显存与带宽受限、专家权重常驻与按需换入结合”这一档位描述，没有给出具体显存 GB 数、带宽 GB/s、算力 TFLOPS，也没有给出模型参数量与专家数。这意味着它的结果只能作为“机制存在性”证据，不能作为“性能绝对值”证据。工程读者要建立的判断是：当一篇端侧 MoE 论文只给机制不给档位数字时，它的 TTFT/TPOT 曲线只能用来验证趋势方向（热点排队是否被削平、尾延迟是否随容量因子动态化而下降），不能用来做容量规划输入。</p>\n<p>三层口径之间还存在耦合。模型档决定专家权重总量与单 token 激活参数量，直接约束设备档能否常驻全部专家；设备档的带宽决定分组 GEMM 的算术强度上限；负载档的长尾程度决定热度表滑动窗口该取多长。论文把“离线校准估计专家热度先验与容量因子初值、运行时滑动窗口在线更新”作为部署期参数，正是承认这三层耦合无法在训练期固定。基准报告若不交代滑动窗口长度与校准集长尾形态，读者就无法判断热度表滞后是否被低估——而这恰恰是论文自己列出的失败模式之一。</p>\n<div class=\"formula\">$$\\text{cost}(b)=\\sum_{e}\\max\\left(0,\\frac{n_e(b)}{C_e}-1\\right)\\cdot L_e+\\lambda\\cdot\\text{KV}(b)$$</div>\n<p>这个代价式是理解全部基准数字的钥匙。$n_e(b)$ 是批 $b$ 内落到专家 $e$ 的 token 数，$C_e$ 是该专家的容量因子（可容纳 token 上限），$L_e$ 是专家 $e$ 的单 token 排队/执行代价，$\\text{KV}(b)$ 是该批的 KV 占用，$\\lambda$ 把显存压力折算进同一量纲。第一项是溢出惩罚：只有 $n_e&gt;C_e$ 的部分才计入，这正是“热点专家排队”的数学形态；第二项是显存惩罚。基准里任何“尾延迟下降”的主张，本质上都是在说这个和式在长尾批次上的上界被压低了。读者应把每个报告的延迟数字反推：它压低的是第一项（重路由削峰）还是第二项（KV 压缩换出），两者对应的系统代价完全不同——前者花的是重路由的额外门控与统计开销，后者花的是换入换出的带宽。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-40\">四十 · batch 与并发不是两个独立旋钮</h3>\n<p>在 D²MoE 的调度层里，批窗口与容量因子是同一组决策的两个输出，而不是两个可以分别调的超参。调度层读专家热度表与 KV 水位，同时决定“这一窗口放多少请求”和“每个专家给多少容量”。这带来一个基准陷阱：如果报告只写“batch=某值下的吞吐”，而不写该 batch 对应的容量因子与 KV 水位档位，那么这个吞吐数字是不可复现的，因为同一 batch 在不同容量因子下会走完全不同的重路由路径。论文材料明确“批大小随水位下调以守住尾延迟”，说明 batch 是水位的内生函数，不是外生设定。</p>\n<p>并发维度同理。解码阶段逐 token 路由使批内专家分布快速漂移，同一批在预填时是热点集中的、在解码几十步后可能已经分散。因此“并发度”在端侧 MoE 里必须和“解码步数”一起报告，否则测到的只是预填瞬间的专家分布。工程上可操作的基准口径是：固定请求长度分布与到达率，扫描 KV 水位档位，记录每个档位下的批窗口、容量因子、尾延迟三者轨迹，而不是只报一个平均吞吐。论文未给出这些轨迹数字，读者只能确认机制闭环存在，不能确认闭环增益幅度。</p>\n<ul>\n<li>预填窗口按 SLO 预算切分，窗口大小受 KV 水位约束，不是固定值。</li>\n<li>解码批随水位下调，下调触发点是尾延迟逼近预算，而非固定阈值。</li>\n<li>容量因子随热度滑动窗口更新，长尾突变时限制重路由幅度以抑制批内抖动。</li>\n</ul>\n<p>一个具体例子：长尾混合请求批次到达，调度层先切预填窗口，token 级门控给出 top-k 专家，热度表显示某专家队列超容量因子，二次路由把溢出 token 重分配到低负载副本，分组 GEMM 按专家聚合执行；随后解码阶段 KV 水位上升，触发块压缩与冷门专家换出，批大小随水位下调。这个链条里，batch 的变化是结果不是原因。基准若把 batch 当自变量报告，就把因果方向搞反了。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-41\">四十一 · 指标怎么读：TTFT、TPOT、吞吐、显存、功耗各自的口径</h3>\n<p>TTFT 在端侧 MoE 里主要由预填窗口切分与专家权重换入决定。论文的“预填与解码共享专家权重但分时复用”意味着预填阶段可能要先换入冷门专家权重，这段换入时间计入 TTFT。因此 TTFT 的可比性取决于“权重常驻比例”这一未报告参数：常驻比例高则 TTFT 短但显存压力大，常驻比例低则 TTFT 长但显存碎片少。读者看到 TTFT 数字时必须问：这是全常驻下的还是按需换入下的？论文材料未给该比例，故 TTFT 只能定性读作“受换入策略支配”。</p>\n<p>TPOT 的口径更微妙。解码逐 token 路由，每个 token 的专家集合可能不同，分组 GEMM 的组大小随批内专家分布变化。TPOT 的均值会被热点步拉高，尾部分布才是 SLO 相关量。论文以尾延迟为主约束，说明它关心的是 TPOT 的高分位而非均值。基准报告若只给平均 TPOT，就掩盖了重路由削峰真正作用的那部分。系统代价上，重路由本身要花额外门控与统计开销，这部分开销摊在每 token 上会抬高 TPOT 基线，收益则体现在高分位被压低——两者必须在同一张分布图上看，单点均值无法体现取舍。</p>\n<table class=\"mini\">\n<thead><tr><th>指标</th><th>主要受控机制</th><th>可比性前提</th><th>系统代价归属</th></tr></thead>\n<tbody>\n<tr><td>TTFT</td><td>预填窗口切分、权重换入</td><td>需报告权重常驻比例</td><td>换入带宽、显存占用</td></tr>\n<tr><td>TPOT 均值</td><td>分组 GEMM 组大小、重路由开销</td><td>需报告批内专家分布</td><td>门控与统计算力</td></tr>\n<tr><td>TPOT 高分位</td><td>二次路由削峰、容量因子动态化</td><td>需报告滑动窗口长度</td><td>重路由抖动风险</td></tr>\n<tr><td>吞吐</td><td>批窗口 × 容量因子联合决策</td><td>需报告 KV 水位档位</td><td>显存碎片、换出带宽</td></tr>\n<tr><td>显存峰值</td><td>KV 分档压缩、冷门专家换出</td><td>需报告压缩档位</td><td>压缩/解压算力、精度损失</td></tr>\n<tr><td>功耗</td><td>常驻专家比例、换入频率</td><td>需报告设备功耗墙</td><td>带宽活动功耗</td></tr>\n</tbody>\n</table>\n<p>显存与功耗两项在论文材料里只有定性描述：“KV 按水位分档压缩与换出，冷门专家按需换入，热点专家权重常驻，形成显存与带宽的折中”。这句话本身就是口径声明：显存峰值下降是用带宽换来的，功耗则随换入频率上升。任何只报显存下降不报带宽代价的读数都是不完整的。功耗在端侧尤其关键，因为功耗墙会反过来压低可持续带宽，形成“换出越多、带宽越紧、换入越慢”的正反馈，这正是热度表滞后在突变负载下可能被放大的物理原因。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-42\">四十二 · 哪些提升不可比：四类典型错配</h3>\n<p>第一类错配是模型档不同。不同专家数、不同 top-k、不同专家粒度的 MoE，其路由熵与热点集中度天然不同，二次路由的削峰空间也不同。论文未给模型档数字，读者无法判断其削峰幅度是模型特性还是机制贡献。第二类错配是设备档不同：单设备端侧的带宽与显存约束下，容量因子动态化的收益主要来自显存碎片削减；换到带宽更宽、显存更大的设备，同一机制的收益结构会变，因为瓶颈从显存转到算力或通信。论文自己声明“单设备场景结论不能直接外推到多设备专家并行与分离式预填/解码的容量规划”，这就是不可比性的官方边界。</p>\n<p>第三类错配是负载档不同。长尾混合请求与均匀短请求下，热度表的滑动窗口统计特性完全不同：长尾突变会让滞后估计过度重路由，均匀负载则几乎不触发二次路由。论文把“长尾突变时需限制重路由幅度避免抖动”列为部署期约束，说明其基准负载必须含突变成分才有意义；若换成平稳负载，动态容量因子相对固定容量因子的尾延迟优势会被压缩。第四类错配是基线缺失。材料明确“未给出具体数据集与基线数字”，因此任何“比固定容量因子快多少”的说法都无法核验，只能作为机制主张读。</p>\n<ul>\n<li>跨模型比：专家数与 top-k 不同，路由熵不同，削峰空间不可平移。</li>\n<li>跨设备比：瓶颈从显存转到算力/通信后，动态容量因子的收益结构改变。</li>\n<li>跨负载比：平稳负载下二次路由几乎不触发，机制增益被稀释。</li>\n<li>跨基线比：无基线数字时，只能验证趋势不能验证幅度。</li>\n</ul>\n<p>还有一个隐蔽的不可比点：量化方案。材料明确“量化方案材料未给出”“数值精度收益未验证”。分组 GEMM 的组大小与数值精度共同决定算术强度，若一侧用高精度、另一侧用低精度，吞吐差异会被误读为调度机制贡献。读者应把“精度未报告”视为该基准的硬缺口，而不是可忽略的脚注。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-43\">四十三 · 消融该怎么读：三个可核验维度与它们的代价</h3>\n<p>论文材料给出可核验的消融维度应围绕三点：token 级路由与负载感知二次路由的取舍、动态容量因子与固定容量因子的尾延迟对比、KV 压缩档位对显存与 SLO 的影响。具体结果未给出，但这三点的读法可以预先建立。第一点读的是“二次路由的净收益”：关掉二次路由后，热点专家队列长度上升，尾延迟高分位抬升，但每 token 门控开销下降，TPOT 均值可能反而更低。因此这一维度的正确读法是看高分位与均值的分离度，而不是看单一吞吐。</p>\n<p>第二点读的是容量因子的动态化价值。固定容量因子在长尾批次下要么过小导致溢出惩罚第一项爆炸，要么过大导致显存碎片抬高第二项。动态化把这两项在运行时重新平衡，代价是热度表滞后带来的抖动风险。消融若只报尾延迟下降不报抖动幅度，就漏掉了机制的另一半成本。第三点读 KV 压缩档位：压缩比例按显存水位分档设定，档位越激进显存峰值越低但压缩/解压算力与精度损失越大，SLO 达成率可能先升后降。这一维度必须同时报显存峰值、SLO 达成率与精度指标，缺一不可。</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{hit}}=\\Pr\\left[\\text{TPOT}_{p99}\\le T_{\\text{budget}}\\ \\wedge\\ \\text{TTFT}_{p99}\\le T_{\\text{first}}\\right]$$</div>\n<p>把 SLO 达成率写成联合概率而非单指标，是读消融的正确姿势。动态容量因子可能改善 TPOT 高分位却因重路由开销轻微恶化 TTFT，联合概率才能反映净效果。论文以尾延迟为主约束，说明它优化的正是这个联合概率的尾部，而不是均值吞吐。工程判断上，读者应要求消融报告给出每个档位下的联合达成率与对应显存峰值，否则无法判断机制是在“削峰”还是在“转移瓶颈”。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-44\">四十四 · 把基准读成容量规划的输入边界</h3>\n<p>最终落到工程判断：D²MoE 的基准材料能支撑的结论只有机制层——容量因子从静态超参变为运行时决策变量、专家热度与 KV 水位进入批调度闭环、预填与解码共享权重分时复用。这些机制可以直接迁移到分离式预填/解码的容量规划，因为那里的预填与解码资源竞争正是同一类问题。但迁移时必须重新标定三层口径：目标设备的显存与带宽决定常驻比例，目标负载的长尾形态决定滑动窗口长度与重路由幅度上限，目标 SLO 的尾部分位决定容量因子的动态范围。论文未给这些数字，迁移者必须自己做离线校准，用校准集上的尾延迟约束确定门控与重路由阈值，用显存水位分档确定 KV 压缩比例。</p>\n<p>一个可操作的落地检查清单：先测目标设备上专家权重的常驻可行比例，再测长尾负载下热度表滑动窗口的估计滞后步数，最后用代价式反推容量因子的安全下限——下限过低会触发溢出惩罚第一项，过高会抬高显存惩罚第二项。这三步都不依赖论文的具体数字，只依赖论文给出的机制结构与代价式形态。若目标场景是多设备专家并行，则论文的单设备结论只能作为“路由侧削峰”的参考，调度侧的容量因子动态化需重新设计，因为跨设备 All-to-All 的代价结构与本地的分组 GEMM 完全不同。这就是把基准读成输入边界而非结论的全部含义：机制可借，数字不可搬。</p>\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-45\">四十五 · 迁移到非 MoE 稠密模型：双路由失去作用点</h3>\n<p>D²MoE 的两个路由动作都建立在“token 到专家的稀疏分配”这一前提上。token 级 top-k 门控产生候选专家集合，负载感知二次路由在候选集合之外寻找低负载副本。稠密模型没有专家维度，门控矩阵退化为恒等映射，二次路由的重分配目标不存在，调度层维护的专家热度表也就没有可统计的键。把系统搬到稠密模型上，能保留的只有调度层中与 KV 水位相关的部分：批窗口按 SLO 预算切分、KV 块按水位压缩与换出、预填与解码分时复用权重。这三件事与路由无关，属于显存与带宽管理，可以直接复用。</p>\n<p>判断标准很直接：模型每层前馈是否为多专家结构、单 token 激活的参数占比是否显著低于总参数量。若激活占比接近 1，双路由的收益归零，而它引入的门控开销与热度统计开销仍然存在。此时应把路由层整体摘除，只保留调度层与执行层的分组 GEMM 骨架——分组 GEMM 在稠密模型上退化为普通 GEMM，分组边界由批内序列长度决定而非专家 id。</p>\n<p>代价体现在两个方向。摘除路由层节省的是每 token 一次 top-k 排序与一次热度表查表的开销，这部分在端侧单设备上并非可忽略：门控需要在每层每个 token 上执行，长预填窗口下累计的排序开销会挤占本已紧张的算力预算。保留调度层则继续承担 KV 水位采样与批窗口重算的周期开销，这部分与模型类型无关，属于固定成本。一个具体例子：把同一套调度层套到稠密 7B 模型上，专家热度表恒为空，二次路由分支永不触发，容量因子退化为常数，系统行为等价于一个带 KV 分档压缩的固定批调度器——功能正确，但论文主张的尾延迟削平机制不再生效。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-46\">四十六 · 迁移到不同专家粒度与共享专家结构：重路由的自由度被压缩</h3>\n<p>二次路由的可行性取决于“同一专家存在多个低负载副本”或“存在语义相近的替代专家”。论文的表述是“把溢出 token 重分配到低负载副本”，副本机制在单设备上意味着同一专家的权重有多份驻留或可分时换入，这直接消耗显存。若目标模型的专家粒度更细（专家数量多、单专家参数少），副本的显存代价下降，重路由自由度上升；若专家粒度更粗（单专家参数大），一份副本就足以吃掉可观的显存预算，重路由从“重分配”退化为“排队等待换入”，尾延迟收益被换入带宽抵消。</p>\n<p>共享专家结构是另一个边界。带共享专家的 MoE（每层有一个始终激活的专家）会把一部分计算从路由路径上剥离，token 级门控只在非共享专家上做 top-k。此时热度表的统计口径需要区分共享与非共享，否则共享专家的恒定高热度会污染容量因子的估计，使调度层误判整体负载。工程上应把共享专家的计数从热度表中剔除，只对可路由专家做滑动窗口统计。</p>\n<div class=\"formula\">$$\\text{cost}(b)=\\sum_{e}\\max\\left(0,\\frac{n_e(b)}{C_e}-1\\right)\\cdot L_e+\\lambda\\cdot\\text{KV}(b)$$</div>\n<p>该式中的 $n_e(b)$ 是批 $b$ 内分配到专家 $e$ 的 token 数，$C_e$ 是该专家的容量因子，$L_e$ 是单 token 在该专家上的排队与执行代价。共享专家若被计入求和，$n_e(b)$ 恒为正且随批大小线性增长，$\\max(0,\\cdot)$ 项在批较大时持续为正，$\\text{cost}(b)$ 被系统性高估，调度层会过早收缩批窗口。这不是数值精度问题，而是统计口径错误导致的容量误判。迁移时必须重写热度表的键空间。</p>\n<p>系统代价：专家粒度变粗时，副本显存占用上升，KV 可用的显存水位下降，KV 压缩档位被迫提前触发，解码阶段的块换出频率上升，尾延迟的方差增大。粒度变细时，分组 GEMM 的分组数上升，单组 token 数下降，GEMM 的算术强度降低，带宽成为瓶颈——分组过多会让分组 GEMM 退化为大量小矩阵乘，端侧带宽受限的平台上这部分损失不可忽视。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-47\">四十七 · 迁移到多设备与分离式预填/解码：单设备假设失效</h3>\n<p>论文明确只讨论单设备，未涉及跨设备专家并行与 All-to-All。把双路由搬到多设备时，二次路由的重分配目标从“本设备低负载副本”变为“远端设备上的专家”，重分配动作变成一次跨设备 token 传输，其代价由互联带宽决定而非本地显存。此时 $\\text{cost}(b)$ 需要增加一项跨设备传输代价，且容量因子 $C_e$ 的定义要从“本设备队列长度上限”改为“本设备可接纳的远端溢出量”，两者语义不同，不能直接沿用。</p>\n<p>分离式预填/解码是更现实的迁移场景。论文的调度层已经把预填与解码的资源竞争作为问题之一，并用分时复用专家权重来缓解。在分离部署下，预填节点与解码节点各自维护热度表与 KV 水位，两份统计互相不可见，二次路由在预填侧做出的重分配决策无法约束解码侧的批窗口。可行的做法是把热度表做成跨节点的轻量共享状态，只同步专家级的聚合计数而非逐 token 路由结果，同步周期与 SLO 预算挂钩：尾延迟约束越紧，同步越频繁，通信开销越高。</p>\n<p>规模上限在这里显现。单设备上热度表的更新是本地内存写，延迟在纳秒到微秒量级；跨节点同步引入网络往返，端侧场景通常没有低延迟互联，同步周期被迫拉长，热度估计的滞后加剧。论文自己指出的“热度表与 KV 水位估计存在滞后，长尾突变下重路由可能抖动”在多设备下会被放大：滞后从本地统计窗口的滞后变成网络同步加统计窗口的双重滞后。判断是：双路由的收益随设备数增加而衰减，除非互联带宽与同步机制能把滞后压回单设备水平，否则多设备扩展应优先做静态专家放置而非动态重路由。</p>\n<p>具体例子：一个两设备部署，预填在设备 A、解码在设备 B。设备 A 的热度表显示专家 $e$ 队列超容量因子，二次路由把溢出 token 重分配到设备 B 上的副本。这次重分配使设备 B 的 KV 写入量上升，解码侧水位提前触发压缩，批窗口收缩，尾延迟反而变差。单设备上不存在的这种跨阶段耦合，是迁移到分离式架构时必须重新建模的部分。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-48\">四十八 · 迁移到不同领域负载：长尾形态决定调度层参数是否成立</h3>\n<p>调度层的三个运行时变量——批窗口、容量因子、KV 压缩档位——都由离线校准给出的初值和运行时滑动窗口更新共同决定。校准集上的尾延迟约束确定了门控与重路由阈值，这个阈值与领域的请求长度分布强相关。把系统迁到请求长度分布不同的领域，阈值必须重标定，否则会出现两种失效：阈值过松，热点专家排队不被触发重路由，尾延迟约束被突破；阈值过紧，正常波动即触发重路由，批内路由抖动，分组 GEMM 的分组边界频繁变化，执行层的聚合效率下降。</p>\n<p>长尾程度是判断迁移成本的核心指标。论文的请求形态是短请求与长预填混合到达，长尾突变是主要风险。若目标领域的请求长度分布更集中（例如固定长度的批量任务），滑动窗口统计的方差下降，热度表滞后问题缓解，容量因子可以退化为准静态参数，动态调整的收益变小而开销仍在——此时应关闭动态容量因子，回到固定容量因子加 KV 分档压缩的简单组合。若目标领域的请求长度分布更分散，长尾突变更频繁，重路由抖动成为主要矛盾，需要限制重路由幅度，论文提到的“限制重路由幅度避免抖动”正是针对这一情形，但幅度上限的取值需要按领域的尾延迟预算重新校准。</p>\n<p>系统代价：重标定本身需要一轮离线校准，校准集必须覆盖目标领域的长尾形态，否则阈值不可信。校准的成本是一次性的，但校准集偏差带来的运行时尾延迟损失是持续的。工程判断是：领域迁移的可行性取决于能否获得代表性校准集，而非算法本身的可移植性。没有校准集，动态容量因子不如固定容量因子稳。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-49\">四十九 · 数值精度与底层实现的迁移空白</h3>\n<p>论文材料未给出量化精度方案，也未给出分组 GEMM 的底层实现细节。这意味着迁移到具体硬件档位时，数值精度这一层是空的，需要迁移者自行补齐。分组 GEMM 在低精度下的行为与稠密 GEMM 不同：不同专家的 token 数差异大，分组内 token 数少的专家在低精度累加时更容易受舍入影响，分组边界的对齐要求也随精度变化。端侧平台若支持 FP8 或更低精度，分组 GEMM 的累加器精度选择会直接影响数值稳定性，而论文没有给出可核验的结论。</p>\n<p>迁移时的具体机制缺口有三处：其一，门控的 top-k 选择在低精度下是否保持稳定，排序对量化误差敏感，阈值附近的 token 可能在不同精度档位下被分配到不同专家，导致热度表统计漂移；其二，二次路由的重分配决策依赖置信度输出，置信度的量化误差会改变重分配幅度；其三，KV 块压缩的比例按显存水位分档设定，压缩后的 KV 在低精度下参与注意力计算，其数值误差与专家权重的量化误差叠加，尾延迟约束下的可接受误差边界未定义。</p>\n<p>系统代价：补齐这三处需要额外的数值验证工作，验证成本落在迁移者身上而非论文。判断是：在未给出量化方案的条件下，双路由的机制收益可以在浮点精度下复现，但低精度下的收益与稳定性不可预设。迁移到支持低精度的端侧平台时，应先在浮点精度下验证调度层的尾延迟收益，再逐档引入量化，每档单独核验热度表统计是否漂移。</p>\n\n<h3 id=\"paper-d-2-moe-dual-routing-and-dynamic-sch-2025-sec-50\">五十 · 规模上限与适用边界的工程判断</h3>\n<p>把上述几条收敛成一个判断：D²MoE 的适用边界由三个条件共同界定——单设备、专家可路由且存在重分配自由度、领域请求形态可校准。三个条件同时成立时，双路由加动态调度的机制是自洽的：token 级门控给出候选，二次路由削平热点队列，调度层用热度表与 KV 水位闭环调整批窗口与容量因子，执行层用分组 GEMM 与分时复用把显存压力摊平。任一条件不成立，收益衰减的方向是明确的：稠密模型上路由层失效，粗粒度专家上重路由退化为换入等待，多设备上滞后放大导致抖动，不可校准的领域上动态参数不如静态参数稳。</p>\n<p>规模上限不在参数量，而在“单设备可容纳的专家副本数与 KV 水位余量”。副本数决定了二次路由的自由度，KV 余量决定了压缩档位触发前能容纳多少并发。两者共同约束了 $\\text{cost}(b)$ 中 $\\lambda\\cdot\\text{KV}(b)$ 项的可行域：KV 余量越小，$\\lambda$ 的相对权重越大，调度层越倾向于收缩批窗口而非重路由，双路由的实际作用被压缩到很窄的区间。工程上应先测出目标设备上“副本显存 + KV 余量”的可行组合，再判断双路由是否有发挥空间；若可行区间窄到只剩一两个容量因子档位，动态调整的收益不足以覆盖其统计开销，应退回静态容量因子。</p>\n<p>最后一个具体机制上的判断落在重路由幅度限制上。论文把“限制重路由幅度避免抖动”作为长尾突变下的必要约束，这个约束的实现方式决定了系统的稳定性上限：幅度限制过严，热点队列削不平；过松，批内路由抖动使分组 GEMM 的分组数在相邻批次间跳变，执行层的权重换入换出节奏被打乱，带宽开销上升。可行的做法是把幅度限制与滑动窗口的统计置信度绑定——窗口内样本少时限制幅度，样本多时放开，使重路由决策的激进程度随估计可靠性变化。这一机制不依赖具体模型或领域，是迁移时可以保留的核心工程约束。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">D$^{2}$MoE: Dual Routing </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">and Dynamic Sc…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · D$^{2}$MoE: Dual Routin… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>未给出</td></tr><tr><td>基线</td><td>未给出</td></tr><tr><td>主要结果</td><td>材料未给出具体数据集与基线数字；论文主张在端侧显存约束下通过双路由与动态调…</td></tr><tr><td>消融</td><td>材料未给出消融实验数字；可核验的消融维度应围绕token级路由与负载感知二…</td></tr><tr><td>局限</td><td>端侧单设备算力与带宽有限，双路由引入额外门控与统计开销；热度表与KV水位估…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-d-2-moe-dual-routing-and-dynamic-sch-2025 · 共 9 个片段</p>\n";break;}}})();
